1	//! Content quality scoring and similarity-based quarantine detection.
2	//!
3	//! ## Scoring weights
4	//!
5	//! | Dimension    | Weight | Basis                                               |
6	//! |--------------|--------|-----------------------------------------------------|
7	//! | Completeness | 50 %   | presence of title, body, category, tags, date, URL  |
8	//! | Accuracy     | 30 %   | structural validity (URL scheme, body/title length) |
9	//! | Timeliness   | 20 %   | publish_date age (recent = higher score)            |
10	//!
11	//! Total below 85 blocks publishing (see `QualityScore::is_publishable`).
12	//!
13	//! ## Similarity quarantine
14	//!
15	//! Uses PostgreSQL pg_trgm `similarity()` to detect near-duplicates in
16	//! `content_pages.body` at the threshold defined in `shared::rules`.
17	
18	use chrono::{NaiveDate, Utc};
19	use rust_decimal::Decimal;
20	use sqlx::PgPool;
21	use uuid::Uuid;
22	
23	use shared::QualityScore;
24	
25	use super::pipeline::TransformedItem;
26	use crate::error::AppResult;
27	
28	// ── Result ────────────────────────────────────────────────────────────────────
29	
30	#[derive(Debug)]
31	pub struct ScoredItem {
32	    pub score:             QualityScore,
33	    pub issues:            Vec<String>,
34	    pub is_quarantined:    bool,
35	    pub quarantine_reason: Option<String>,
36	}
37	
38	// ── Scorer ────────────────────────────────────────────────────────────────────
39	
40	pub struct QualityScorer;
41	
42	impl QualityScorer {
43	    /// Score a transformed item.
44	    ///
45	    /// `existing_content_id` — when re-scoring an existing page, pass its UUID
46	    /// so the similarity check excludes that page from the comparison set.
47	    pub async fn score(
48	        item:                &TransformedItem,
49	        pool:                &PgPool,
50	        existing_content_id: Option<Uuid>,
51	    ) -> AppResult<ScoredItem> {
52	        let mut issues: Vec<String> = Vec::new();
53	
54	        let completeness = score_completeness(item, &mut issues);
55	        let accuracy     = score_accuracy(item, &mut issues);
56	        let timeliness   = score_timeliness(item.publish_date, &mut issues);
57	
58	        let score = QualityScore::compute(
59	            dec(completeness),
60	            dec(accuracy),
61	            dec(timeliness),
62	        );
63	
64	        let (is_quarantined, quarantine_reason) =
65	            check_similarity(item, pool, existing_content_id).await?;
66	
67	        Ok(ScoredItem { score, issues, is_quarantined, quarantine_reason })
68	    }
69	}
70	
71	// ── Completeness (50 %) ───────────────────────────────────────────────────────
72	
73	fn score_completeness(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
74	    let mut present = 0usize;
75	    const FIELDS: usize = 6;
76	
77	    if !item.title.is_empty()    { present += 1; } else { issues.push("missing_title".into()); }
78	    if !item.body.is_empty()     { present += 1; } else { issues.push("missing_body".into()); }
79	    if item.category != "general"{ present += 1; } else { issues.push("default_category".into()); }
80	    if !item.tags.is_empty()     { present += 1; } else { issues.push("no_tags".into()); }
81	    if item.publish_date.is_some(){ present += 1; } else { issues.push("missing_publish_date".into()); }
82	    if item.source_url.is_some() { present += 1; } else { issues.push("missing_source_url".into()); }
83	
84	    (present as f64 / FIELDS as f64) * 100.0
85	}
86	
87	// ── Accuracy (30 %) ───────────────────────────────────────────────────────────
88	
89	fn score_accuracy(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
90	    let mut score: f64 = 100.0;
91	
92	    if item.body.len() < 50 {
93	        score -= 40.0;
94	        issues.push("short_body".into());
95	    }
96	    if item.title.len() < 5 {
97	        score -= 20.0;
98	        issues.push("short_title".into());
99	    }
100	    if let Some(url) = &item.source_url {
101	        let ok = url.starts_with("http://")
102	            || url.starts_with("https://")
103	            || url.starts_with("file://");
104	        if !ok {
105	            score -= 20.0;
106	            issues.push("invalid_source_url_scheme".into());
107	        }
108	    }
109	    if item.tags.len() > 20 {
110	        score -= 10.0;
111	        issues.push("too_many_tags".into());
112	    }
113	
114	    score.max(0.0)
115	}
116	
117	// ── Timeliness (20 %) ─────────────────────────────────────────────────────────
118	
119	fn score_timeliness(publish_date: Option<NaiveDate>, issues: &mut Vec<String>) -> f64 {
120	    let today = Utc::now().date_naive();
121	    match publish_date {
122	        None => {
123	            issues.push("unknown_publish_date".into());
124	            50.0
125	        }
126	        Some(date) => {
127	            let age = (today - date).num_days();
128	            if age < 0      { 100.0 }
129	            else if age <= 30  { 100.0 }
130	            else if age <= 90  { 70.0 }
131	            else if age <= 365 { 40.0 }
132	            else {
133	                issues.push("stale_content".into());
134	                10.0
135	            }
136	        }
137	    }
138	}
139	
140	// ── Similarity quarantine ─────────────────────────────────────────────────────
141	
142	/// Check whether the item body is a near-duplicate of any existing content.
143	///
144	/// Returns `(true, Some(reason))` when a duplicate is found at the configured
145	/// similarity threshold (`shared::rules::SIMILARITY_QUARANTINE`).
146	async fn check_similarity(
147	    item:                &TransformedItem,
148	    pool:                &PgPool,
149	    existing_content_id: Option<Uuid>,
150	) -> AppResult<(bool, Option<String>)> {
151	    // Short stubs would produce too many false-positive similarity matches.
152	    if item.body.len() < 100 {
153	        return Ok((false, None));
154	    }
155	
156	    let threshold = shared::rules::SIMILARITY_QUARANTINE as f32;
157	
158	    // similarity() returns float4 (real) in PostgreSQL, so we compare as real.
159	    // We cast the result to float8 for decoding into Rust f64.
160	    let row: Option<(Uuid, f64)> = sqlx::query_as(
161	        "SELECT id, similarity(body, $1)::float8 AS sim
162	         FROM content_pages
163	         WHERE ($2::UUID IS NULL OR id <> $2)
164	           AND similarity(body, $1) >= $3::real
165	         ORDER BY sim DESC
166	         LIMIT 1",
167	    )
168	    .bind(&item.body)
169	    .bind(existing_content_id)
170	    .bind(threshold)
171	    .fetch_optional(pool)
172	    .await
173	    .map_err(crate::error::AppError::Database)?;
174	
175	    match row {
176	        Some((dup_id, sim)) => Ok((
177	            true,
178	            Some(format!("near_duplicate of content_id={dup_id} (similarity={sim:.2})")),
179	        )),
180	        None => Ok((false, None)),
181	    }
182	}
183	
