461	// ── Subscription handlers ──────────────────────────────────────────────────────
462	
463	pub async fn list_subscriptions(
464	    pool: web::Data<sqlx::PgPool>,
465	    auth: RequireViewContractors,
466	) -> AppResult<HttpResponse> {
467	    // Returns subscriptions held by the current user as both dispatcher and contractor.
468	    let dispatcher_subs = SubscriptionRepo::new(&pool)
469	        .list_for_subscriber("dispatcher", auth.id)
470	        .await?;
471	    let contractor_subs = SubscriptionRepo::new(&pool)
472	        .list_for_subscriber("contractor", auth.id)
473	        .await?;
474	    let mut all = dispatcher_subs;
475	    all.extend(contractor_subs);
476	    Ok(HttpResponse::Ok().json(all))
477	}
478	
479	pub async fn subscribe(
480	    pool: web::Data<sqlx::PgPool>,
481	    body: web::Json<SubscribeBody>,
482	    auth: RequireViewContractors,
483	) -> AppResult<HttpResponse> {
484	    let body = body.into_inner();
485	    if !matches!(body.subscriber_type.as_str(), "dispatcher" | "contractor") {
486	        return Err(AppError::Validation(
487	            "subscriber_type must be 'dispatcher' or 'contractor'".into(),
488	        ));
489	    }
490	    if !matches!(body.target_type.as_str(), "shift" | "route") {
491	        return Err(AppError::Validation(
492	            "target_type must be 'shift' or 'route'".into(),
493	        ));
494	    }
495	    SubscriptionRepo::new(&pool)
496	        .subscribe(&body.subscriber_type, auth.id, &body.target_type, body.target_id)
497	        .await?;
498	    Ok(HttpResponse::Ok().json(json!({ "ok": true })))
499	}
500	
501	pub async fn unsubscribe(
502	    pool: web::Data<sqlx::PgPool>,
503	    body: web::Json<SubscribeBody>,
504	    auth: RequireViewContractors,
505	) -> AppResult<HttpResponse> {
506	    let body = body.into_inner();
507	    SubscriptionRepo::new(&pool)
508	        .unsubscribe(&body.subscriber_type, auth.id, &body.target_type, body.target_id)
509	        .await?;
510	    Ok(HttpResponse::Ok().json(json!({ "ok": true })))
511	}
