133	/// POST /credentials — upload a credential document via multipart form.
134	///
135	/// Form fields:
136	///   `contractor_id`  (text, UUID)
137	///   `document_type`  (text, e.g. "conductor_license")
138	///   `expires_at`     (text, YYYY-MM-DD, optional)
139	///   `file`           (binary, PDF/JPEG/PNG, ≤ 10 MB)
140	pub async fn upload_credential(
141	    pool:  web::Data<sqlx::PgPool>,
142	    mut mp: Multipart,
143	    auth:  RequireViewCredentials,
144	) -> AppResult<HttpResponse> {
145	    let mut contractor_id: Option<Uuid>   = None;
146	    let mut document_type: Option<String> = None;
147	    let mut expires_at:    Option<NaiveDate> = None;
148	    let mut file_name:     Option<String> = None;
149	    let mut file_bytes:    Option<BytesMut> = None;
150	    let mut mime_type:     Option<String> = None;
151	
152	    // ── Parse multipart fields ─────────────────────────────────────────────
153	    while let Some(mut field) = mp
154	        .try_next()
155	        .await
156	        .map_err(|e| AppError::Validation(e.to_string()))?
157	    {
158	        let name = field.name().map(|s| s.to_owned()).unwrap_or_default();
159	
160	        match name.as_str() {
161	            "contractor_id" => {
162	                let text = read_text_field(&mut field).await?;
163	                contractor_id = Some(
164	                    Uuid::parse_str(text.trim())
165	                        .map_err(|_| AppError::Validation("Invalid contractor_id UUID".into()))?,
166	                );
167	            }
168	            "document_type" => {
169	                document_type = Some(read_text_field(&mut field).await?);
170	            }
171	            "expires_at" => {
172	                let s = read_text_field(&mut field).await?;
173	                if !s.trim().is_empty() {
174	                    expires_at = Some(
175	                        NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d")
176	                            .map_err(|_| {
177	                                AppError::Validation(
178	                                    "expires_at must be YYYY-MM-DD".into(),
179	                                )
180	                            })?,
181	                    );
182	                }
183	            }
184	            "file" => {
185	                // Content-Type for this part.
186	                let ct = field
187	                    .content_type()
188	                    .map(|m| m.to_string())
189	                    .unwrap_or_default();
190	                mime_type = Some(ct);
191	
192	                // Filename from Content-Disposition.
193	                // content_disposition() returns Option<&ContentDisposition>
194	                // in actix-multipart 0.7.x; use and_then to reach get_filename.
195	                file_name = field
196	                    .content_disposition()
197	                    .and_then(|cd| cd.get_filename())
198	                    .map(|s| s.to_owned());
199	
200	                // Stream bytes with size guard.
201	                let mut buf = BytesMut::new();
202	                while let Some(chunk) = field
203	                    .try_next()
204	                    .await
205	                    .map_err(|e| AppError::Validation(e.to_string()))?
206	                {
207	                    buf.extend_from_slice(&chunk);
208	                    if buf.len() > MAX_UPLOAD_BYTES as usize {
209	                        return Err(AppError::FileTooLarge);
210	                    }
211	                }
212	                file_bytes = Some(buf);
213	            }
214	            _ => {
215	                // Drain unknown fields.
216	                while let Some(_) = field
217	                    .try_next()
218	                    .await
219	                    .map_err(|e| AppError::Validation(e.to_string()))?
220	                {}
221	            }
222	        }
223	    }
224	
225	    // ── Validate required fields ───────────────────────────────────────────
226	    let contractor_id = contractor_id
227	        .ok_or_else(|| AppError::Validation("contractor_id is required".into()))?;
228	    let document_type = document_type
229	        .map(|s| s.trim().to_owned())
230	        .filter(|s| !s.is_empty())
231	        .ok_or_else(|| AppError::Validation("document_type is required".into()))?;
232	    let file_bytes = file_bytes
233	        .ok_or_else(|| AppError::Validation("file field is required".into()))?;
234	    let file_name = file_name
235	        .ok_or_else(|| AppError::Validation("file must include a filename".into()))?;
236	    let mime_type = mime_type.unwrap_or_default();
237	
238	    if file_bytes.is_empty() {
239	        return Err(AppError::Validation("file is empty".into()));
240	    }
241	
242	    // ── MIME type validation ───────────────────────────────────────────────
243	    if !matches!(
244	        mime_type.as_str(),
245	        "application/pdf" | "image/jpeg" | "image/png"
246	    ) {
247	        return Err(AppError::UnsupportedFileType(mime_type));
248	    }
249	
250	    // ── SHA-256 fingerprint + duplicate check ──────────────────────────────
251	    let mut hasher = Sha256::new();
252	    hasher.update(&file_bytes);
253	    let fingerprint = hex::encode(hasher.finalize());
254	
255	    if let Some(dup_id) = CredentialRepo::new(&pool)
256	        .find_by_fingerprint(&fingerprint)
257	        .await?
258	    {
259	        return Err(AppError::Conflict(format!(
260	            "Duplicate document — already stored as credential {dup_id}"
261	        )));
262	    }
263	
264	    // ── Verify contractor exists ───────────────────────────────────────────
265	    ContractorRepo::new(&pool)
266	        .find_by_id(contractor_id)
267	        .await?
268	        .ok_or_else(|| AppError::NotFound(format!("Contractor {contractor_id}")))?;
269	
270	    // ── Store file ─────────────────────────────────────────────────────────
271	    let upload_dir =
272	        std::env::var("UPLOAD_DIR").unwrap_or_else(|_| "/app/uploads".to_owned());
273	    let ctr_dir = format!("{upload_dir}/contractors/{contractor_id}");
274	    tokio::fs::create_dir_all(&ctr_dir).await?;
275	
276	    // Sanitize filename (strip path components and dangerous chars).
277	    let safe_name = file_name
278	        .chars()
279	        .map(|c| if c.is_alphanumeric() || c == '.' || c == '-' { c } else { '_' })
280	        .collect::<String>();
281	    let fp_prefix = &fingerprint[..8];
282	    let stored_name    = format!("{fp_prefix}_{safe_name}");
283	    let relative_path  = format!("contractors/{contractor_id}/{stored_name}");
284	    let absolute_path  = format!("{upload_dir}/{relative_path}");
285	
286	    // Encrypt file at rest using AES-256-GCM
287	    let encrypted = encrypt_file_bytes(&file_bytes, &upload_secret())?;
288	    tokio::fs::write(&absolute_path, &encrypted).await?;
289	
290	    // ── Create credential record ───────────────────────────────────────────
291	    let cmd = CreateCredential {
292	        contractor_id,
293	        document_type: document_type.clone(),
294	        file_name,
295	        file_path:       relative_path,
296	        file_size_bytes: file_bytes.len() as i32,
297	        mime_type,
298	        fingerprint,
299	        expires_at,
300	        uploaded_by: Some(auth.id),
301	    };
302	    let cred_id = CredentialRepo::new(&pool).create(&cmd).await?;
303	
304	    // ── Audit records ──────────────────────────────────────────────────────
305	    CredAuditRepo::new(&pool)
306	        .insert(
307	            cred_id, "uploaded", Some(auth.id), None, None,
308	            Some(json!({ "via": "web_upload", "size_bytes": file_bytes.len() })),
309	        )
310	        .await?;
311	
312	    write_audit(
313	        &pool,
314	        "credential_uploaded", "credential", Some(cred_id),
315	        Some(auth.id), "upload",
316	        None,
317	        Some(json!({ "document_type": &document_type, "contractor_id": contractor_id })),
318	        None,
319	    )
320	    .await;
321	
322	    Ok(HttpResponse::Created().json(json!({ "id": cred_id })))
323	}
