391	/// POST /credentials/{id}/esign — attach an internal e-signature to a credential.
392	pub async fn esign_credential(
393	    pool:  web::Data<sqlx::PgPool>,
394	    path:  web::Path<Uuid>,
395	    body:  web::Json<EsignBody>,
396	    auth:  RequireApproveCredentials,
397	) -> AppResult<HttpResponse> {
398	    let id = path.into_inner();
399	    CredentialRepo::new(&pool)
400	        .find_by_id(id)
401	        .await?
402	        .ok_or_else(|| AppError::NotFound(format!("Credential {id}")))?;
403	
404	    if body.signer_name.trim().is_empty() {
405	        return Err(AppError::Validation("signer_name is required".into()));
406	    }
407	    let signed_date = NaiveDate::parse_from_str(&body.signed_date, "%Y-%m-%d")
408	        .map_err(|_| AppError::Validation("signed_date must be YYYY-MM-DD".into()))?;
409	
410	    // Save drawn signature if provided — fail the request if storage fails.
411	    let sig_path = if let Some(ref sig_data) = body.signature_data {
412	        if !sig_data.is_empty() {
413	            let upload_dir = std::env::var("UPLOAD_DIR").unwrap_or_else(|_| "/app/uploads".to_owned());
414	            let sig_dir = format!("{upload_dir}/signatures");
415	            tokio::fs::create_dir_all(&sig_dir).await?;
416	            let ts = chrono::Utc::now().timestamp();
417	            let sig_file = format!("{sig_dir}/{id}_{ts}.svg");
418	            tokio::fs::write(&sig_file, sig_data.as_bytes()).await?;
419	            Some(format!("signatures/{id}_{ts}.svg"))
420	        } else { None }
421	    } else { None };
422	
423	    let cmd = CreateEsignature {
424	        entity_type:          "credential".to_owned(),
425	        entity_id:            id,
426	        signer_name:          body.signer_name.trim().to_owned(),
427	        signed_date,
428	        signature_image_path: sig_path,
429	    };
430	    let sig_id = EsignatureRepo::new(&pool).create(&cmd).await?;
431	
432	    CredAuditRepo::new(&pool)
433	        .insert(
434	            id, "esigned", Some(auth.id),
435	            Some(body.signer_name.trim()),
436	            None,
437	            Some(json!({ "sig_id": sig_id, "signed_date": &body.signed_date })),
438	        )
439	        .await?;
440	
441	    write_audit(
442	        &pool,
443	        "credential_esigned", "credential", Some(id),
444	        Some(auth.id), "esign",
445	        None,
446	        Some(json!({ "sig_id": sig_id, "signer_name": body.signer_name.trim() })),
447	        None,
448	    )
449	    .await;
450	
451	    Ok(HttpResponse::Created().json(json!({ "id": sig_id })))
452	}
