1	//! Toast notification hook.
2	//!
3	//! Usage inside any function component:
4	//! ```rust
5	//! let toasts = use_toasts();
6	//! toasts.push.emit(("Saved!".into(), ToastKind::Success));
7	//! // In html!:
8	//! { toasts.view }
9	//! ```
10	//!
11	//! Toasts auto-dismiss after 4 s and can also be closed manually.
12	
13	use wasm_bindgen::JsCast;
14	use yew::prelude::*;
15	
16	// ── Data types ─────────────────────────────────────────────────────────────────
17	
18	#[derive(Clone, PartialEq, Debug)]
19	pub enum ToastKind {
20	    Success,
21	    Error,
22	    Warning,
23	    Info,
24	}
25	
26	#[derive(Clone, PartialEq, Debug)]
27	pub struct ToastItem {
28	    pub id:      u32,
29	    pub message: String,
30	    pub kind:    ToastKind,
31	}
32	
33	// ── Return value from use_toasts ───────────────────────────────────────────────
34	
35	pub struct UseToasts {
36	    /// Emit to display a new toast.
37	    pub push: Callback<(String, ToastKind)>,
38	    /// Include this in your `html!` tree to render the toast stack.
39	    pub view: Html,
40	}
41	
42	// ── Hook ───────────────────────────────────────────────────────────────────────
43	
44	#[yew::hook]
45	pub fn use_toasts() -> UseToasts {
46	    let items   = use_state(|| Vec::<ToastItem>::new());
47	    let next_id = use_state(|| 0u32);
48	
49	    let push = {
50	        let items   = items.clone();
51	        let next_id = next_id.clone();
52	        Callback::from(move |(message, kind): (String, ToastKind)| {
53	            let id = *next_id + 1;
54	            next_id.set(id);
55	
56	            let mut v = (*items).clone();
57	            v.push(ToastItem { id, message, kind });
58	            items.set(v);
59	
60	            // Auto-dismiss after 4 s.
61	            let items = items.clone();
62	            gloo_timers::callback::Timeout::new(4_000, move || {
63	                items.set(
64	                    (*items).iter().filter(|t| t.id != id).cloned().collect(),
65	                );
66	            })
67	            .forget();
68	        })
69	    };
70	
71	    let view = render_stack(&items);
72	    UseToasts { push, view }
73	}
74	
75	// ── Rendering ──────────────────────────────────────────────────────────────────
76	
77	fn render_stack(items: &UseStateHandle<Vec<ToastItem>>) -> Html {
78	    if items.is_empty() {
79	        return html! {};
80	    }
81	
82	    let toasts: Html = items
83	        .iter()
84	        .map(|t| render_one(t, items.clone()))
85	        .collect();
86	
87	    html! {
88	        <div
89	            aria-live="polite"
90	            aria-atomic="false"
91	            class="fixed bottom-6 right-6 z-[9999] flex flex-col gap-2 pointer-events-none"
92	        >
93	            { toasts }
94	        </div>
95	    }
96	}
97	
98	fn render_one(t: &ToastItem, items: UseStateHandle<Vec<ToastItem>>) -> Html {
99	    let id = t.id;
100	    let on_close = {
101	        let items = items.clone();
102	        Callback::from(move |_: MouseEvent| {
103	            items.set((*items).iter().filter(|t| t.id != id).cloned().collect());
104	        })
105	    };
106	
107	    let (bg, border_l, icon_html, text_cls) = match t.kind {
108	        ToastKind::Success => (
109	            "bg-white",
110	            "border-l-emerald-500",
111	            html! { <span class="text-emerald-500">
112	                { crate::components::icons::check_circle("w-5 h-5") }
113	            </span> },
114	            "text-slate-800",
115	        ),
116	        ToastKind::Error => (
117	            "bg-white",
118	            "border-l-red-500",
119	            html! { <span class="text-red-500">
120	                { crate::components::icons::x_circle("w-5 h-5") }
121	            </span> },
122	            "text-slate-800",
123	        ),
124	        ToastKind::Warning => (
125	            "bg-white",
126	            "border-l-amber-500",
127	            html! { <span class="text-amber-500">
128	                { crate::components::icons::exclamation_triangle("w-5 h-5") }
129	            </span> },
130	            "text-slate-800",
131	        ),
132	        ToastKind::Info => (
133	            "bg-white",
134	            "border-l-sky-500",
135	            html! { <span class="text-sky-500">
136	                { crate::components::icons::information_circle("w-5 h-5") }
137	            </span> },
138	            "text-slate-800",
139	        ),
140	    };
141	
142	    html! {
143	        <div
144	            role="alert"
145	            class={format!(
146	                "pointer-events-auto flex items-start gap-3 rounded-lg border border-slate-200 \
147	                 border-l-4 {border_l} {bg} pl-3 pr-4 py-3 shadow-panel \
148	                 min-w-[300px] max-w-sm animate-fade-in"
149	            )}
150	        >
151	            { icon_html }
152	            <p class={format!("flex-1 text-sm font-medium {text_cls}")}>
153	                { &t.message }
154	            </p>
155	            <button
156	                onclick={on_close}
157	                aria-label="Dismiss"
158	                class="shrink-0 text-slate-400 hover:text-slate-600 transition-colors mt-0.5"
159	            >
160	                { crate::components::icons::x_mark("w-4 h-4") }
161	            </button>
162	        </div>
163	    }
164	}
