35	/// Compute HMAC-SHA-256 request signature required by the auth middleware.
36	/// Returns (sig_hex, timestamp_string).
37	fn sign(method: &str, path: &str, token: &str) -> (String, String) {
38	    let ts = std::time::SystemTime::now()
39	        .duration_since(std::time::UNIX_EPOCH)
40	        .unwrap()
41	        .as_secs() as i64;
42	    let message = format!("{method}\n{path}\n{ts}");
43	    type HmacSha256 = Hmac<Sha256>;
44	    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
45	        .expect("HMAC accepts any key length");
46	    mac.update(message.as_bytes());
47	    let sig = hex::encode(mac.finalize().into_bytes());
48	    (sig, ts.to_string())
49	}
