56	        .json(&json!({ "username": ADMIN_USER, "password": ADMIN_PASS }))
57	        .send()
58	        .await
59	        .expect("login request");
60	    assert_eq!(r.status(), StatusCode::OK, "admin login failed — is the server running?");
61	    let body: Value = r.json().await.expect("login response JSON");
62	    body["token"]
63	        .as_str()
