68	/// Authenticated GET request with proper HMAC signature headers.
69	async fn authed_get(c: &Client, path: &str, token: &str) -> reqwest::Response {
70	    let (sig, ts) = sign("GET", path, token);
71	    c.get(format!("{}{path}", base()))
72	        .bearer_auth(token)
73	        .header("X-RailOps-Sig", sig)
74	        .header("X-RailOps-Ts", ts)
75	        .send()
76	        .await
77	        .unwrap_or_else(|e| panic!("GET {path} failed: {e}"))
78	}
