377	fn results_panel(
378	    results:      &UseStateHandle<Option<SearchResponse>>,
379	    loading:      &UseStateHandle<bool>,
380	    error:        &UseStateHandle<Option<String>>,
381	    active_q:     &str,
382	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
383	) -> Html {
384	    if **loading {
385	        return html! {
386	            <div class="space-y-4">
387	                { for (0..6).map(|_| html! {
388	                    <div class="bg-white rounded-2xl border border-slate-200 p-5 animate-pulse">
389	                        <div class="h-4 bg-slate-200 rounded-full w-20 mb-3"></div>
390	                        <div class="h-5 bg-slate-200 rounded w-4/5 mb-2"></div>
391	                        <div class="h-3 bg-slate-100 rounded w-16"></div>
392	                    </div>
393	                }) }
394	            </div>
395	        };
396	    }
397	
398	    if let Some(msg) = &**error {
399	        return html! {
400	            <div class="rounded-xl bg-red-50 border border-red-200 p-6 text-red-700">
401	                <p class="font-semibold mb-1">{"Unable to load results"}</p>
402	                <p class="text-sm">{ msg.clone() }</p>
403	            </div>
404	        };
405	    }
406	
407	    if let Some(resp) = &**results {
408	        let heading = match resp.search_type.as_deref() {
409	            Some("fts")   => format!("{} results for \"{}\"", resp.total, active_q),
410	            Some("fuzzy") => format!(
411	                "Showing approximate matches for \"{}\" ({} results)",
412	                active_q, resp.total
413	            ),
414	            _ if !active_q.is_empty() => format!("No results for \"{}\"", active_q),
415	            _ => format!("{} articles", resp.total),
416	        };
417	
418	        if resp.items.is_empty() {
419	            return html! {
420	                <div class="text-center py-16">
421	                    <p class="text-lg font-semibold text-slate-700 mb-2">
422	                        { format!("No results for \"{active_q}\"") }
423	                    </p>
424	                    <p class="text-slate-500 text-sm">
425	                        {"Try different keywords, or browse by category."}
426	                    </p>
427	                </div>
428	            };
429	        }
430	
431	        let is_fuzzy = resp.search_type.as_deref() == Some("fuzzy");
432	
433	        html! {
434	            <div>
435	                <div class="flex items-center justify-between mb-4">
436	                    <p class="text-sm text-slate-600">{ heading }</p>
437	                    if is_fuzzy {
438	                        <span class="text-xs text-amber-700 bg-amber-50 border border-amber-200
439	                                     rounded-full px-2.5 py-1 font-medium">
440	                            {"Approximate matches"}
441	                        </span>
442	                    }
443	                </div>
444	
445	                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
446	                    { for resp.items.iter().map(article_card) }
447	                </div>
448	
449	                // Pagination
450	                if resp.total_pages > 1 {
451	                    { pagination(resp.page, resp.total_pages, make_page_cb) }
452	                }
453	            </div>
454	        }
455	    } else {
456	        html! {
457	            <div class="text-center py-16 text-slate-400">
458	                <p>{"Start typing to search, or browse by category."}</p>
459	            </div>
460	        }
461	    }
462	}
