464	fn pagination(
465	    current:      i64,
466	    total:        i64,
467	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
468	) -> Html {
469	    html! {
470	        <div class="flex items-center justify-center gap-2">
471	            <button
472	                onclick={make_page_cb(1)}
473	                disabled={current == 1}
474	                class={page_btn_class(false, current == 1)}
475	            >{"«"}</button>
476	            <button
477	                onclick={make_page_cb((current - 1).max(1))}
478	                disabled={current == 1}
479	                class={page_btn_class(false, current == 1)}
480	            >{"‹"}</button>
481	
482	            { for visible_pages(current, total).into_iter().map(|p| {
483	                let active = p == current;
484	                html! {
485	                    <button
486	                        key={p}
487	                        onclick={make_page_cb(p)}
488	                        class={page_btn_class(active, false)}
489	                    >
490	                        { p }
491	                    </button>
492	                }
493	            }) }
494	
495	            <button
496	                onclick={make_page_cb((current + 1).min(total))}
497	                disabled={current == total}
498	                class={page_btn_class(false, current == total)}
499	            >{"›"}</button>
500	            <button
501	                onclick={make_page_cb(total)}
502	                disabled={current == total}
503	                class={page_btn_class(false, current == total)}
504	            >{"»"}</button>
505	        </div>
506	    }
507	}
508	
509	fn visible_pages(current: i64, total: i64) -> Vec<i64> {
510	    let window = 2i64;
511	    let start  = (current - window).max(1);
512	    let end    = (current + window).min(total);
513	    (start..=end).collect()
514	}
515	
516	fn page_btn_class(active: bool, disabled: bool) -> &'static str {
517	    if disabled      { "w-9 h-9 rounded-lg text-sm text-slate-300 cursor-not-allowed" }
518	    else if active   { "w-9 h-9 rounded-lg text-sm bg-indigo-700 text-white font-bold" }
519	    else             { "w-9 h-9 rounded-lg text-sm border border-slate-200 \
520	                        text-slate-700 hover:bg-slate-50" }
521	}
522	
523	fn sidebar_btn_class(active: bool) -> &'static str {
524	    if active {
525	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
526	         bg-indigo-50 text-indigo-700 font-semibold text-sm"
527	    } else {
528	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
529	         text-slate-700 text-sm hover:bg-slate-50 transition"
530	    }
531	}
