40	pub struct QualityScorer;
41	
42	impl QualityScorer {
43	    /// Score a transformed item.
44	    ///
45	    /// `existing_content_id` — when re-scoring an existing page, pass its UUID
46	    /// so the similarity check excludes that page from the comparison set.
47	    pub async fn score(
48	        item:                &TransformedItem,
49	        pool:                &PgPool,
50	        existing_content_id: Option<Uuid>,
51	    ) -> AppResult<ScoredItem> {
52	        let mut issues: Vec<String> = Vec::new();
53	
54	        let completeness = score_completeness(item, &mut issues);
55	        let accuracy     = score_accuracy(item, &mut issues);
56	        let timeliness   = score_timeliness(item.publish_date, &mut issues);
57	
58	        let score = QualityScore::compute(
59	            dec(completeness),
60	            dec(accuracy),
61	            dec(timeliness),
62	        );
63	
64	        let (is_quarantined, quarantine_reason) =
65	            check_similarity(item, pool, existing_content_id).await?;
66	
67	        Ok(ScoredItem { score, issues, is_quarantined, quarantine_reason })
68	    }
69	}
