325	/// PATCH /credentials/{id}/review — approve or reject a pending credential.
326	pub async fn review_credential(
327	    pool:  web::Data<sqlx::PgPool>,
328	    path:  web::Path<Uuid>,
329	    body:  web::Json<ReviewBody>,
330	    auth:  RequireApproveCredentials,
331	) -> AppResult<HttpResponse> {
332	    let id   = path.into_inner();
333	    let cred = CredentialRepo::new(&pool)
334	        .find_by_id(id)
335	        .await?
336	        .ok_or_else(|| AppError::NotFound(format!("Credential {id}")))?;
337	
338	    if cred.status != "pending" {
339	        return Err(AppError::Validation(format!(
340	            "Credential is already '{}' — only pending credentials can be reviewed",
341	            cred.status
342	        )));
343	    }
344	    if !matches!(body.status.as_str(), "approved" | "rejected") {
345	        return Err(AppError::Validation(
346	            "status must be 'approved' or 'rejected'".into(),
347	        ));
348	    }
349	
350	    CredentialRepo::new(&pool)
351	        .review(id, &body.status, auth.id, body.review_notes.as_deref(), Utc::now())
352	        .await?;
353	
354	    let action = body.status.as_str(); // "approved" | "rejected"
355	    let data = body.review_notes.as_ref().map(|n| json!({ "notes": n }));
356	
357	    CredAuditRepo::new(&pool)
358	        .insert(id, action, Some(auth.id), None, None, data.clone())
359	        .await?;
360	
361	    write_audit(
362	        &pool,
363	        "credential_reviewed", "credential", Some(id),
364	        Some(auth.id), action,
365	        Some(json!({ "status": "pending" })),
366	        Some(json!({ "status": &body.status, "notes": &body.review_notes })),
367	        None,
368	    )
369	    .await;
370	
371	    Ok(HttpResponse::Ok().json(json!({ "ok": true, "status": &body.status })))
372	}
