549	/// Drain a non-file multipart field into a UTF-8 String.
550	async fn read_text_field(field: &mut actix_multipart::Field) -> AppResult<String> {
551	    let mut buf = BytesMut::new();
552	    while let Some(chunk) = field
553	        .try_next()
554	        .await
555	        .map_err(|e| AppError::Validation(e.to_string()))?
556	    {
557	        buf.extend_from_slice(&chunk);
558	        if buf.len() > 4096 {
559	            return Err(AppError::Validation("Form field value too long".into()));
560	        }
561	    }
562	    String::from_utf8(buf.to_vec())
563	        .map_err(|_| AppError::Validation("Form field is not valid UTF-8".into()))
564	}
565	
566	/// Encrypt raw bytes with AES-256-GCM. Returns nonce (12B) || ciphertext.
567	fn encrypt_file_bytes(data: &[u8], secret: &str) -> Result<Vec<u8>, AppError> {
568	    use aes_gcm::{aead::{Aead, AeadCore, KeyInit, OsRng}, Aes256Gcm, Nonce};
569	    let key_bytes = crate::crypto::derive_aes_key(secret);
570	    let cipher = Aes256Gcm::new_from_slice(&key_bytes)
571	        .map_err(|e| AppError::Internal(anyhow::anyhow!("AES key error: {e}")))?;
572	    let nonce = Aes256Gcm::generate_nonce(&mut OsRng);
573	    let ciphertext = cipher.encrypt(&nonce, data)
574	        .map_err(|e| AppError::Internal(anyhow::anyhow!("AES encrypt error: {e}")))?;
575	    let mut out = nonce.to_vec();
576	    out.extend(ciphertext);
577	    Ok(out)
578	}
579	
580	/// Decrypt bytes produced by encrypt_file_bytes.
581	fn decrypt_file_bytes(blob: &[u8], secret: &str) -> Result<Vec<u8>, AppError> {
582	    use aes_gcm::{aead::{Aead, KeyInit}, Aes256Gcm, Nonce};
583	    if blob.len() < 12 {
584	        return Err(AppError::Validation("Encrypted blob too short".into()));
585	    }
586	    let (nonce_bytes, ciphertext) = blob.split_at(12);
587	    let key_bytes = crate::crypto::derive_aes_key(secret);
588	    let cipher = Aes256Gcm::new_from_slice(&key_bytes)
589	        .map_err(|e| AppError::Internal(anyhow::anyhow!("AES key error: {e}")))?;
590	    let nonce = Nonce::from_slice(nonce_bytes);
591	    cipher.decrypt(nonce, ciphertext)
592	        .map_err(|e| AppError::Internal(anyhow::anyhow!("AES decrypt error: {e}")))
593	}
594	
595	fn upload_secret() -> String {
596	    std::env::var("SESSION_SECRET")
597	        .unwrap_or_else(|_| "change_this_to_a_random_64_char_string_before_going_live_!!1".to_owned())
598	}
