496	    body:  web::Json<CreateEsignBody>,
497	    auth:  RequireViewCredentials,
498	) -> AppResult<HttpResponse> {
499	    if !matches!(
500	        body.entity_type.as_str(),
501	        "credential" | "order" | "assignment"
502	    ) {
503	        return Err(AppError::Validation(
504	            "entity_type must be credential | order | assignment".into(),
505	        ));
506	    }
507	    if body.signer_name.trim().is_empty() {
508	        return Err(AppError::Validation("signer_name is required".into()));
509	    }
510	    let signed_date = NaiveDate::parse_from_str(&body.signed_date, "%Y-%m-%d")
511	        .map_err(|_| AppError::Validation("signed_date must be YYYY-MM-DD".into()))?;
512	
513	    let sig_path = if let Some(ref sig_data) = body.signature_data {
514	        if !sig_data.is_empty() {
515	            let upload_dir = std::env::var("UPLOAD_DIR").unwrap_or_else(|_| "/app/uploads".to_owned());
516	            let sig_dir = format!("{upload_dir}/signatures");
517	            tokio::fs::create_dir_all(&sig_dir).await?;
518	            let ts = chrono::Utc::now().timestamp();
519	            let sig_file = format!("{sig_dir}/{}_{ts}.svg", body.entity_id);
520	            tokio::fs::write(&sig_file, sig_data.as_bytes()).await?;
521	            Some(format!("signatures/{}_{ts}.svg", body.entity_id))
522	        } else { None }
523	    } else { None };
524	
525	    let cmd = CreateEsignature {
526	        entity_type:          body.entity_type.clone(),
527	        entity_id:            body.entity_id,
528	        signer_name:          body.signer_name.trim().to_owned(),
529	        signed_date,
530	        signature_image_path: sig_path,
531	    };
532	    let sig_id = EsignatureRepo::new(&pool).create(&cmd).await?;
533	
534	    write_audit(
535	        &pool,
536	        "esignature_created", &body.entity_type, Some(body.entity_id),
537	        Some(auth.id), "esign",
538	        None,
539	        Some(json!({ "sig_id": sig_id, "signer_name": body.signer_name.trim() })),
540	        None,
541	    )
542	    .await;
543	
544	    Ok(HttpResponse::Created().json(json!({ "id": sig_id })))
545	}
