1	//! Typed API client for the RailOps backend.
2	//!
3	//! Every request (except /auth/login) is signed:
4	//!   message   = "METHOD\nPATH\nUNIX_TIMESTAMP_SECS"
5	//!   key       = raw Bearer token
6	//!   signature = HMAC-SHA-256(key, message) — hex-encoded
7	//!
8	//! Headers added automatically:
9	//!   Authorization: Bearer <token>
10	//!   X-RailOps-Ts:  <unix_epoch_secs>
11	//!   X-RailOps-Sig: <hmac_hex>
12	
13	pub mod credentials;
14	pub mod kiosk;
15	pub mod ops;
16	pub mod rules;
17	pub mod staffing;
18	
19	use gloo_net::http::{Request, Response};
20	use hmac::{Hmac, Mac};
21	use serde::{de::DeserializeOwned, Serialize};
22	use sha2::Sha256;
23	
24	use crate::auth::CurrentUser;
25	
26	// ── Error ─────────────────────────────────────────────────────────────────────
27	
28	#[derive(Debug, Clone)]
29	pub struct ApiError {
30	    pub status:  u16,
31	    pub message: String,
32	}
33	
34	impl std::fmt::Display for ApiError {
35	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
36	        write!(f, "HTTP {}: {}", self.status, self.message)
37	    }
38	}
39	
40	pub type ApiResult<T> = Result<T, ApiError>;
41	
42	// ── Request / response shapes mirroring the backend ──────────────────────────
43	
44	#[derive(serde::Serialize)]
45	pub struct LoginPayload<'a> {
46	    pub username: &'a str,
47	    pub password: &'a str,
48	}
49	
50	#[derive(serde::Deserialize)]
51	pub struct LoginResponse {
52	    pub token:      String,
53	    pub user:       CurrentUser,
54	    pub expires_at: String,
55	}
56	
57	// ── Public API functions ──────────────────────────────────────────────────────
58	
59	/// Authenticate and receive a session token.
60	pub async fn login(username: &str, password: &str) -> ApiResult<LoginResponse> {
61	    let body = LoginPayload { username, password };
62	    // Login is unsigned (no token yet).
63	    post_unsigned("/api/v1/auth/login", &body).await
64	}
65	
66	/// Invalidate the current session.
67	pub async fn logout(token: &str) -> ApiResult<()> {
68	    signed_request("DELETE", "/api/v1/auth/logout", token, None::<&()>).await?;
69	    Ok(())
70	}
71	
72	/// Fetch the authenticated user's info (used to verify a stored token on load).
73	pub async fn me(token: &str) -> ApiResult<CurrentUser> {
74	    let resp = signed_request("GET", "/api/v1/auth/me", token, None::<&()>).await?;
75	    parse_json(resp).await
76	}
77	
78	// ── Internal helpers ──────────────────────────────────────────────────────────
79	
80	async fn post_unsigned<B: Serialize, R: DeserializeOwned>(
81	    path: &str,
82	    body: &B,
83	) -> ApiResult<R> {
84	    let body_str = serde_json::to_string(body).map_err(|e| ApiError {
85	        status:  0,
86	        message: e.to_string(),
87	    })?;
88	
89	    let resp = Request::post(path)
90	        .header("Content-Type", "application/json")
91	        .body(body_str)
92	        .map_err(|e| ApiError { status: 0, message: e.to_string() })?
93	        .send()
94	        .await
95	        .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
96	
97	    parse_json(resp).await
98	}
99	
100	pub(crate) async fn signed_request<B: Serialize>(
101	    method:  &str,
102	    path:    &str,
103	    token:   &str,
104	    body:    Option<&B>,
105	) -> ApiResult<Response> {
106	    let ts      = unix_now();
107	    let message = format!("{method}\n{path}\n{ts}");
108	    let sig     = hmac_sign(token, &message);
109	
110	    let mut builder = match method {
111	        "GET"    => Request::get(path),
112	        "POST"   => Request::post(path),
113	        "PUT"    => Request::put(path),
114	        "PATCH"  => Request::patch(path),
115	        "DELETE" => Request::delete(path),
116	        m        => return Err(ApiError { status: 0, message: format!("Unknown method {m}") }),
117	    };
118	
119	    builder = builder
120	        .header("Authorization", &format!("Bearer {token}"))
121	        .header("X-RailOps-Ts",  &ts.to_string())
122	        .header("X-RailOps-Sig", &sig);
123	
124	    let resp = if let Some(b) = body {
125	        let body_str = serde_json::to_string(b).map_err(|e| ApiError {
126	            status: 0, message: e.to_string(),
127	        })?;
128	        builder
129	            .header("Content-Type", "application/json")
130	            .body(body_str)
131	            .map_err(|e| ApiError { status: 0, message: e.to_string() })?
132	            .send()
133	            .await
134	    } else {
135	        builder
136	            .send()
137	            .await
138	    }
139	    .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
140	
141	    if resp.ok() {
142	        Ok(resp)
143	    } else {
144	        let status = resp.status();
145	        let text   = resp.text().await.unwrap_or_default();
146	        // Try to extract the backend's structured error message.
147	        let message = serde_json::from_str::<serde_json::Value>(&text)
148	            .ok()
149	            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
150	            .unwrap_or(text);
151	        Err(ApiError { status, message })
152	    }
153	}
