100	pub(crate) async fn signed_request<B: Serialize>(
101	    method:  &str,
102	    path:    &str,
103	    token:   &str,
104	    body:    Option<&B>,
105	) -> ApiResult<Response> {
106	    let ts      = unix_now();
107	    let message = format!("{method}\n{path}\n{ts}");
108	    let sig     = hmac_sign(token, &message);
109	
110	    let mut builder = match method {
111	        "GET"    => Request::get(path),
112	        "POST"   => Request::post(path),
113	        "PUT"    => Request::put(path),
114	        "PATCH"  => Request::patch(path),
115	        "DELETE" => Request::delete(path),
116	        m        => return Err(ApiError { status: 0, message: format!("Unknown method {m}") }),
117	    };
118	
119	    builder = builder
120	        .header("Authorization", &format!("Bearer {token}"))
121	        .header("X-RailOps-Ts",  &ts.to_string())
122	        .header("X-RailOps-Sig", &sig);
123	
124	    let resp = if let Some(b) = body {
125	        let body_str = serde_json::to_string(b).map_err(|e| ApiError {
126	            status: 0, message: e.to_string(),
127	        })?;
128	        builder
129	            .header("Content-Type", "application/json")
130	            .body(body_str)
131	            .map_err(|e| ApiError { status: 0, message: e.to_string() })?
132	            .send()
133	            .await
134	    } else {
135	        builder
136	            .send()
137	            .await
138	    }
139	    .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
140	
141	    if resp.ok() {
142	        Ok(resp)
143	    } else {
144	        let status = resp.status();
145	        let text   = resp.text().await.unwrap_or_default();
146	        // Try to extract the backend's structured error message.
147	        let message = serde_json::from_str::<serde_json::Value>(&text)
148	            .ok()
149	            .and_then(|v| v["error"]["message"].as_str().map(|s| s.to_owned()))
150	            .unwrap_or(text);
151	        Err(ApiError { status, message })
152	    }
153	}
