1	//! Kiosk search page.
2	//!
3	//! Features:
4	//! - URL-driven state: all filters are query parameters so results are bookmarkable
5	//! - 300 ms debounced text input
6	//! - Multi-condition filters: full-text query + category + tag
7	//! - FTS results with fuzzy fallback (shown with different heading)
8	//! - Pagination with first/prev/next/last controls
9	//! - Active filter chips with individual remove buttons
10	//! - Tag suggestions sidebar loaded from the API
11	
12	use gloo_timers::callback::Timeout;
13	use wasm_bindgen_futures::spawn_local;
14	use web_sys::HtmlInputElement;
15	use yew::prelude::*;
16	use yew_router::prelude::*;
17	
18	use crate::api::kiosk::{self, category_label, CategoryCount, SearchResponse, TagCount};
19	use crate::app::Route;
20	use crate::pages::kiosk::home::{article_card, footer, nav_bar};
21	
22	// ── URL query params ──────────────────────────────────────────────────────────
23	
24	#[derive(Debug, Clone, PartialEq, serde::Deserialize, serde::Serialize, Default)]
25	pub struct SearchQuery {
26	    #[serde(default, skip_serializing_if = "Option::is_none")]
27	    pub q:        Option<String>,
28	    #[serde(default, skip_serializing_if = "Option::is_none")]
29	    pub category: Option<String>,
30	    #[serde(default, skip_serializing_if = "Option::is_none")]
31	    pub tag:      Option<String>,
32	    #[serde(default, skip_serializing_if = "Option::is_none")]
33	    pub page:     Option<i64>,
34	}
35	
36	// ── Component ─────────────────────────────────────────────────────────────────
37	
38	#[function_component(KioskSearchPage)]
39	pub fn kiosk_search() -> Html {
40	    let location  = use_location().unwrap();
41	    let navigator = use_navigator().unwrap();
42	
43	    // Parse URL query params.
44	    let url_q: SearchQuery = location.query::<SearchQuery>().unwrap_or_default();
45	
46	    // Raw input state (what the user is currently typing — debounced).
47	    let raw_input = use_state(|| url_q.q.clone().unwrap_or_default());
48	
49	    // Committed filter state (what was last submitted to the API).
50	    let committed = use_state(|| url_q.clone());
51	
52	    // Results
53	    let results     = use_state(|| Option::<SearchResponse>::None);
54	    let loading     = use_state(|| false);
55	    let error       = use_state(|| Option::<String>::None);
56	
57	    // Sidebar data
58	    let cat_counts = use_state(|| Vec::<CategoryCount>::new());
59	    let top_tags   = use_state(|| Vec::<TagCount>::new());
60	
61	    // ── Load sidebar data once ────────────────────────────────────────────
62	    {
63	        let cat_counts = cat_counts.clone();
64	        let top_tags   = top_tags.clone();
65	        use_effect_with((), move |_| {
66	            spawn_local(async move {
67	                let (cats, tags) = futures::join!(
68	                    kiosk::list_categories(),
69	                    kiosk::list_tags(),
70	                );
71	                if let Ok(c) = cats { cat_counts.set(c); }
72	                if let Ok(t) = tags { top_tags.set(t); }
73	            });
74	            || ()
75	        });
76	    }
77	
78	    // ── Sync raw_input when URL changes externally (e.g. back/forward) ───
79	    {
80	        let raw_input = raw_input.clone();
81	        let committed = committed.clone();
82	        let q_str     = url_q.q.clone().unwrap_or_default();
83	        use_effect_with(url_q.clone(), move |uq| {
84	            raw_input.set(uq.q.clone().unwrap_or_default());
85	            committed.set(uq.clone());
86	            drop(q_str);
87	            || ()
88	        });
89	    }
90	
91	    // ── Run search whenever committed filter changes ───────────────────────
92	    {
93	        let results  = results.clone();
94	        let loading  = loading.clone();
95	        let error    = error.clone();
96	        use_effect_with((*committed).clone(), move |params| {
97	            let params  = params.clone();
98	            let results = results.clone();
99	            let loading = loading.clone();
100	            let error   = error.clone();
101	
102	            loading.set(true);
103	            error.set(None);
104	
105	            spawn_local(async move {
106	                let q        = params.q.as_deref();
107	                let category = params.category.as_deref();
108	                let tag      = params.tag.as_deref();
109	                let page     = params.page.unwrap_or(1);
110	
111	                match kiosk::search_content(q, category, tag, page, 12).await {
112	                    Ok(r)  => { results.set(Some(r)); loading.set(false); }
113	                    Err(e) => {
114	                        error.set(Some(e.message));
115	                        results.set(None);
116	                        loading.set(false);
117	                    }
118	                }
119	            });
120	            || ()
121	        });
122	    }
123	
124	    // ── Debounce text input → push URL ────────────────────────────────────
125	    {
126	        let navigator = navigator.clone();
127	        let url_q2    = url_q.clone();
128	        let raw_input = raw_input.clone();
129	        use_effect_with((*raw_input).clone(), move |text| {
130	            let text  = text.clone();
131	            let nav   = navigator.clone();
132	            let mut q = url_q2.clone();
133	            let handle = Timeout::new(300, move || {
134	                q.q    = if text.trim().is_empty() { None } else { Some(text.trim().to_owned()) };
135	                q.page = None;
136	                nav.push_with_query(&Route::KioskSearch, &q).ok();
137	            });
138	            move || drop(handle)
139	        });
140	    }
141	
142	    // ── Event handlers ────────────────────────────────────────────────────
143	    let on_input = {
144	        let raw_input = raw_input.clone();
145	        Callback::from(move |e: InputEvent| {
146	            let el: HtmlInputElement = e.target_unchecked_into();
147	            raw_input.set(el.value());
148	        })
149	    };
150	
151	    let on_clear_query = {
152	        let navigator = navigator.clone();
153	        let q = url_q.clone();
154	        Callback::from(move |_: MouseEvent| {
155	            let mut q = q.clone();
156	            q.q    = None;
157	            q.page = None;
158	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
159	        })
160	    };
161	
162	    let make_category_cb = |cat: Option<String>| {
163	        let navigator = navigator.clone();
164	        let q = url_q.clone();
165	        Callback::from(move |_: MouseEvent| {
166	            let mut q = q.clone();
167	            q.category = cat.clone();
168	            q.page     = None;
169	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
170	        })
171	    };
172	
173	    let make_tag_cb = |tag: Option<String>| {
174	        let navigator = navigator.clone();
175	        let q = url_q.clone();
176	        Callback::from(move |_: MouseEvent| {
177	            let mut q = q.clone();
178	            q.tag  = tag.clone();
179	            q.page = None;
180	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
181	        })
182	    };
183	
184	    let make_page_cb = |p: i64| {
185	        let navigator = navigator.clone();
186	        let q = url_q.clone();
187	        Callback::from(move |_: MouseEvent| {
188	            let mut q = q.clone();
189	            q.page = Some(p);
190	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
191	        })
192	    };
193	
194	    // ── Render ────────────────────────────────────────────────────────────
195	    let active_q        = url_q.q.as_deref().unwrap_or("").to_owned();
196	    let active_category = url_q.category.clone();
197	    let active_tag      = url_q.tag.clone();
198	
199	    html! {
200	        <div class="min-h-screen bg-slate-50">
201	            { nav_bar() }
202	
203	            <div class="max-w-6xl mx-auto px-6 py-8">
204	
205	                // ── Search bar ────────────────────────────────────────────
206	                <div class="flex gap-3 mb-6">
207	                    <div class="relative flex-1">
208	                        <input
209	                            type="search"
210	                            placeholder="Search articles…"
211	                            autocomplete="off"
212	                            value={(*raw_input).clone()}
213	                            oninput={on_input}
214	                            class="w-full rounded-xl border border-slate-300 px-5 py-3 pr-10
215	                                   text-base shadow-sm focus:border-indigo-500 focus:outline-none
216	                                   focus:ring-2 focus:ring-indigo-200"
217	                        />
218	                        if !active_q.is_empty() {
219	                            <button
220	                                onclick={on_clear_query}
221	                                class="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400
222	                                       hover:text-slate-700 text-xl leading-none"
223	                                title="Clear search"
224	                            >{"×"}</button>
225	                        }
