52	/// Login as admin and return the raw bearer token.
53	async fn admin_token() -> String {
54	    let c = new_client();
55	    let r = c
56	        .post(format!("{}/api/v1/auth/login", base()))
57	        .json(&json!({ "username": ADMIN_USER, "password": ADMIN_PASS }))
58	        .send()
59	        .await
60	        .expect("login request");
61	    assert_eq!(r.status(), StatusCode::OK, "admin login failed — is the server running?");
62	    let body: Value = r.json().await.expect("login response JSON");
63	    body["token"]
64	        .as_str()
65	        .expect("no token in login response")
66	        .to_owned()
67	}
