    let token = admin_token().await;
    let c = new_client();

    let path = "/api/v1/credentials/c0000000-0000-0000-0000-000000000001/download";
    let (sig, ts) = sign("GET", path, &token);
    let r = c.get(format!("{}{path}", base()))
