465	/// e.g. `"2024-06-15T09:30:00Z"` → `"Jun 15 09:30"`
466	pub fn fmt_dt(iso: &str) -> String {
467	    // Expect at minimum "YYYY-MM-DDTHH:MM"
468	    if iso.len() < 16 { return iso.to_owned(); }
469	    let date = &iso[..10];   // "YYYY-MM-DD"
470	    let time = &iso[11..16]; // "HH:MM"
471	    let parts: Vec<&str> = date.split('-').collect();
472	    if parts.len() < 3 { return iso.to_owned(); }
473	    let month = match parts[1].parse::<u32>().unwrap_or(0) {
474	        1  => "Jan", 2  => "Feb", 3  => "Mar", 4  => "Apr",
475	        5  => "May", 6  => "Jun", 7  => "Jul", 8  => "Aug",
476	        9  => "Sep", 10 => "Oct", 11 => "Nov", 12 => "Dec",
477	        _  => "???",
478	    };
479	    format!("{} {} {}", month, parts[2].trim_start_matches('0'), time)
480	}
