93	    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
94	        // Extract everything we need from the request before entering the async block.
95	        let pool    = req.app_data::<web::Data<PgPool>>()
96	            .cloned()
97	            .expect("PgPool not registered in app_data");
98	        let limiter = req.app_data::<web::Data<RateLimiter>>()
99	            .cloned()
100	            .expect("RateLimiter not registered in app_data");
101	
102	        let method = req.method().as_str().to_uppercase();
103	        let path   = req.path().to_owned();
103	        let qs     = req.query_string().to_owned();
104	
105	        let token = extract_bearer(req);
106	        let ts    = extract_header_i64(req, "X-RailOps-Ts");
106	        let sig   = extract_header_str(req, "X-RailOps-Sig");
107	
108	        Box::pin(async move {
109	            // ── 1. Token present ─────────────────────────────────────────
110	            let raw_token = token.ok_or_else(|| {
111	                AppError::Unauthorized("Missing Authorization: Bearer token".into())
112	            })?;
113	
114	            // ── 2. Signature + timestamp ─────────────────────────────────
115	            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
116	            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
117	
118	            let now = Utc::now().timestamp();
119	            if (now - ts).abs() > 120 {
120	                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
120	            }
121	
122	            // Include query string in the signed message to prevent query-param tampering.
123	            let path_with_query = if qs.is_empty() {
123	                path.clone()
124	            } else {
124	                format!("{path}?{qs}")
125	            };
126	            let message = format!("{method}\n{path_with_query}\n{ts}");
127	            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
128	                warn!(path = %path_with_query, "Invalid request signature");
128	                return Err(AppError::Unauthorized("Invalid request signature".into()));
129	            }
130	
131	            // ── 3. Session lookup ────────────────────────────────────────
132	            let token_hash = crate::crypto::sha256_hex(&raw_token);
133	
134	            let record = session::find_active_session(&pool, &token_hash)
135	                .await?
135	                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
136	
137	            // ── 4. Rate limiting ─────────────────────────────────────────
138	            limiter.check_and_increment(&token_hash)?;
139	
139	            // ── 5. Touch session (reset idle expiry) ─────────────────────
140	            session::touch_session(&pool, &token_hash).await?;
