1	//! `AuthUser` — Actix `FromRequest` extractor that:
2	//!   1. Reads `Authorization: Bearer <token>`
3	//!   2. Verifies the HMAC-SHA-256 request signature (`X-RailOps-Sig` / `X-RailOps-Ts`)
4	//!   3. Looks up the session by `sha256(token)`, enforcing idle + absolute expiry
5	//!   4. Enforces per-session rate limiting (default 60 req/min)
6	//!   5. Bumps `last_active_at` to reset the idle window
7	//!
8	//! Signing protocol:
9	//!   message  = "METHOD\nPATH_WITH_QUERY\nUNIX_TIMESTAMP_SECS"
10	//!   key      = raw Bearer token
11	//!   sig      = HMAC-SHA-256(key, message) — hex-encoded, in X-RailOps-Sig header
12	//!   Timestamp must be within ±120 s of server time.
13	//!
14	//!   PATH_WITH_QUERY = path + "?" + query_string  (if query_string is non-empty)
15	//!                   = path                        (if query_string is empty)
16	//!
17	//! This ensures query parameters are covered by the signature, preventing
18	//! replay attacks that tamper with query string values.
19	
20	use actix_web::{dev::Payload, web, FromRequest, HttpRequest};
21	use chrono::Utc;
22	use dashmap::DashMap;
23	use futures::future::LocalBoxFuture;
24	use sqlx::PgPool;
25	use tracing::warn;
26	use uuid::Uuid;
27	
28	use shared::UserRole;
29	
30	use crate::error::{AppError, AppResult};
31	
32	use super::session;
