34	// ── Rate limiter ──────────────────────────────────────────────────────────────
35	
36	/// In-memory, lock-free rate limiter keyed by session `token_hash`.
37	/// Each entry is `(request_count, window_start_unix_secs)`.
38	pub struct RateLimiter {
39	    store:   DashMap<String, (u32, i64)>,
40	    max_rpm: u32,
41	}
42	
43	impl RateLimiter {
44	    pub fn new(max_rpm: u32) -> Self {
45	        Self { store: DashMap::new(), max_rpm }
46	    }
47	
48	    /// Increment the counter for `key`.  Returns `Err(RateLimited)` if exceeded.
49	    pub fn check_and_increment(&self, key: &str) -> AppResult<()> {
50	        let now = Utc::now().timestamp();
51	        let window = 60_i64; // 1-minute fixed window
52	
53	        let mut entry = self.store.entry(key.to_owned()).or_insert((0, now));
54	        let (count, window_start) = entry.value_mut();
55	
56	        if now - *window_start >= window {
57	            // New window
58	            *window_start = now;
59	            *count = 1;
60	        } else {
61	            *count += 1;
62	            if *count > self.max_rpm {
63	                let retry_after = (window - (now - *window_start)).max(1) as u64;
64	                return Err(AppError::RateLimited { retry_after });
65	            }
66	        }
67	        Ok(())
68	    }
69	
70	    /// Evict entries for expired windows (call periodically to bound memory use).
71	    pub fn evict_expired(&self) {
72	        let now = Utc::now().timestamp();
73	        self.store.retain(|_, (_, window_start)| now - *window_start < 120);
74	    }
75	}
