77	// ── AuthUser ──────────────────────────────────────────────────────────────────
78	
79	/// The authenticated identity injected into every protected handler.
80	#[derive(Debug, Clone)]
81	pub struct AuthUser {
82	    pub id:         Uuid,
83	    pub username:   String,
84	    pub role:       UserRole,
85	    pub full_name:  Option<String>,
86	    /// SHA-256 of the raw token — used for logout / rate-limit key.
87	    pub token_hash: String,
88	}
89	
90	impl FromRequest for AuthUser {
91	    type Error = AppError;
92	    type Future = LocalBoxFuture<'static, AppResult<AuthUser>>;
93	
94	    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
95	        // Extract everything we need from the request before entering the async block.
96	        let pool    = req.app_data::<web::Data<PgPool>>()
97	            .cloned()
98	            .expect("PgPool not registered in app_data");
99	        let limiter = req.app_data::<web::Data<RateLimiter>>()
100	            .cloned()
101	            .expect("RateLimiter not registered in app_data");
102	
103	        let method = req.method().as_str().to_uppercase();
104	        let path   = req.path().to_owned();
105	        let qs     = req.query_string().to_owned();
106	
107	        let token = extract_bearer(req);
108	        let ts    = extract_header_i64(req, "X-RailOps-Ts");
109	        let sig   = extract_header_str(req, "X-RailOps-Sig");
110	
111	        Box::pin(async move {
112	            // ── 1. Token present ─────────────────────────────────────────
113	            let raw_token = token.ok_or_else(|| {
114	                AppError::Unauthorized("Missing Authorization: Bearer token".into())
115	            })?;
116	
117	            // ── 2. Signature + timestamp ─────────────────────────────────
118	            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
119	            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
120	
121	            let now = Utc::now().timestamp();
122	            if (now - ts).abs() > 120 {
123	                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
124	            }
125	
126	            // Include query string in the signed message to prevent query-param tampering.
127	            let path_with_query = if qs.is_empty() {
128	                path.clone()
129	            } else {
130	                format!("{path}?{qs}")
131	            };
132	            let message = format!("{method}\n{path_with_query}\n{ts}");
133	            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
134	                warn!(path = %path_with_query, "Invalid request signature");
135	                return Err(AppError::Unauthorized("Invalid request signature".into()));
136	            }
137	
138	            // ── 3. Session lookup ────────────────────────────────────────
139	            let token_hash = crate::crypto::sha256_hex(&raw_token);
140	
141	            let record = session::find_active_session(&pool, &token_hash)
142	                .await?
143	                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
144	
145	            // ── 4. Rate limiting ─────────────────────────────────────────
146	            limiter.check_and_increment(&token_hash)?;
147	
148	            // ── 5. Touch session (reset idle expiry) ─────────────────────
149	            session::touch_session(&pool, &token_hash).await?;
150	
151	            // Compute role before moving username out of record (E0382 fix:
152	            // user_role() borrows self, which must happen before partial move).
153	            let role = record.user_role();
154	            Ok(AuthUser {
155	                id:         record.user_id,
156	                username:   record.username,
157	                role,
158	                full_name:  record.full_name,
159	                token_hash,
160	            })
161	        })
162	    }
163	}
164	
165	// ── Header extraction helpers ─────────────────────────────────────────────────
166	
167	fn extract_bearer(req: &HttpRequest) -> Option<String> {
168	    req.headers()
169	        .get("Authorization")
170	        .and_then(|v| v.to_str().ok())
171	        .and_then(|v| v.strip_prefix("Bearer "))
172	        .map(|s| s.to_owned())
173	}
174	
175	fn extract_header_i64(req: &HttpRequest, name: &str) -> Option<i64> {
176	    req.headers()
177	        .get(name)
178	        .and_then(|v| v.to_str().ok())
179	        .and_then(|v| v.parse().ok())
180	}
181	
182	fn extract_header_str(req: &HttpRequest, name: &str) -> Option<String> {
183	    req.headers()
184	        .get(name)
185	        .and_then(|v| v.to_str().ok())
186	        .map(|s| s.to_owned())
187	}
