1	//! Typed API client for credential document management and e-signing.
2	
3	use serde::{Deserialize, Serialize};
4	use uuid::Uuid;
5	use wasm_bindgen::JsValue;
6	
7	use super::{parse_json, signed_request, ApiError, ApiResult};
8	
9	// Re-use the pagination wrapper from ops.
10	pub use crate::api::ops::Page;
11	
12	// ── Response types ─────────────────────────────────────────────────────────────
13	
14	#[derive(Debug, Clone, Deserialize)]
15	pub struct CredentialRow {
16	    pub id:              Uuid,
17	    pub contractor_id:   Uuid,
18	    pub document_type:   String,
19	    pub file_name:       String,
20	    pub file_path:       String,
21	    pub file_size_bytes: i32,
22	    pub mime_type:       String,
23	    pub fingerprint:     String,
24	    pub expires_at:      Option<String>,
25	    pub status:          String,
26	    pub uploaded_by:     Option<Uuid>,
27	    pub uploaded_at:     String,
28	    pub reviewed_by:     Option<Uuid>,
29	    pub reviewed_at:     Option<String>,
30	    pub review_notes:    Option<String>,
31	}
32	
33	#[derive(Debug, Clone, Deserialize)]
34	pub struct CredentialAuditEntry {
35	    pub id:            i64,
36	    pub credential_id: Uuid,
37	    pub action:        String,
38	    pub performed_by:  Option<Uuid>,
39	    pub viewer_name:   Option<String>,
40	    pub ip_address:    Option<String>,
41	    pub data:          Option<serde_json::Value>,
42	    pub created_at:    String,
43	}
44	
45	#[derive(Debug, Clone, Deserialize)]
46	pub struct EsignatureRow {
47	    pub id:                   Uuid,
48	    pub entity_type:          String,
49	    pub entity_id:            Uuid,
50	    pub signer_name:          String,
51	    pub signed_date:          String,
52	    pub signature_image_path: Option<String>,
53	    pub created_at:           String,
54	}
55	
56	// ── Request bodies ─────────────────────────────────────────────────────────────
57	
58	#[derive(Debug, Serialize)]
59	pub struct ReviewBody {
60	    pub status:       String,
61	    pub review_notes: Option<String>,
62	}
63	
64	#[derive(Debug, Serialize)]
65	pub struct EsignBody {
66	    pub signer_name: String,
67	    pub signed_date: String,
68	}
69	
70	#[derive(Debug, Serialize)]
71	pub struct CreateEsignBody {
72	    pub entity_type: String,
73	    pub entity_id:   Uuid,
74	    pub signer_name: String,
75	    pub signed_date: String,
76	}
77	
78	// ── API functions ──────────────────────────────────────────────────────────────
79	
80	/// List credentials with optional status filter, paginated.
81	pub async fn list_credentials(
82	    token:         &str,
83	    contractor_id: Option<Uuid>,
84	    status:        Option<&str>,
85	    page:          i64,
86	) -> ApiResult<Page<CredentialRow>> {
87	    let mut path = format!("/api/v1/credentials?page={page}&per_page=20");
88	    if let Some(cid) = contractor_id {
89	        path.push_str(&format!("&contractor_id={cid}"));
90	    }
91	    if let Some(s) = status {
92	        path.push_str(&format!("&status={s}"));
93	    }
94	    let resp = signed_request("GET", &path, token, None::<&()>).await?;
95	    parse_json(resp).await
96	}
97	
98	/// Get a single credential (also logs a "viewed" audit entry on the backend).
99	pub async fn get_credential(token: &str, id: Uuid) -> ApiResult<CredentialRow> {
100	    let path = format!("/api/v1/credentials/{id}");
101	    let resp = signed_request("GET", &path, token, None::<&()>).await?;
102	    parse_json(resp).await
103	}
104	
105	/// Upload a new credential document via multipart form.
106	///
107	/// Caller builds a `web_sys::FormData` with the fields:
108	///   `contractor_id`, `document_type`, `expires_at` (optional), `file`.
109	pub async fn upload_credential(
110	    token:     &str,
111	    form_data: web_sys::FormData,
112	) -> ApiResult<serde_json::Value> {
113	    let path = "/api/v1/credentials";
114	    let ts   = super::unix_now();
115	    let msg  = format!("POST\n{path}\n{ts}");
116	    let sig  = super::hmac_sign(token, &msg);
117	
118	    let resp = gloo_net::http::Request::post(path)
119	        .header("Authorization", &format!("Bearer {token}"))
120	        .header("X-RailOps-Ts",  &ts.to_string())

