1	//! Background crawl engine.
2	//!
3	//! [`CrawlEngine`] runs as a long-lived tokio task that wakes every 60 seconds
4	//! (or immediately when triggered via the [`TriggerHandle`]), queries the DB
5	//! for due tasks, and spawns a bounded worker per task.
6	//!
7	//! ## Worker lifecycle
8	//!
9	//! ```text
10	//! list_due() → [task₁, task₂, …]
11	//!   for each task (bounded by Semaphore):
12	//!     set_running(task)
13	//!     run_id = CrawlRunRepo::start()
14	//!     loop {
15	//!       read_page(cursor) → (items, next_cursor)
16	//!       for each item:
17	//!         transform → fingerprint-dedup → score → ingest / quarantine
18	//!       increment_counters
19	//!       cursor = next_cursor or break if None
20	//!     }
21	//!     CrawlRunRepo::finish()
22	//!     CrawlTaskRepo::complete(cursor, next_crawl_at)
23	//! ```
24	
25	use std::sync::Arc;
26	
27	use chrono::Utc;
28	use serde_json::json;
29	use sqlx::PgPool;
30	use tokio::sync::Semaphore;
31	use tokio::time::{interval, Duration, MissedTickBehavior};
32	use tracing::{error, info, warn};
33	
34	use crate::domain::content::models::CreateContent;
35	use crate::domain::content::repo::ContentRepo;
36	use crate::domain::crawl::models::{CrawlTask, NewQualityLog};
37	use crate::domain::crawl::repo::{CrawlRunRepo, CrawlSourceRepo, CrawlTaskRepo, QualityRepo};
38	
39	use super::pipeline;
40	use super::quality::QualityScorer;
41	use super::reader::reader_for;
42	
43	// ── Trigger handle ────────────────────────────────────────────────────────────
44	
45	/// Allows HTTP handlers to wake the engine without waiting for the next tick.
46	pub struct TriggerHandle {
47	    tx: tokio::sync::watch::Sender<()>,
48	}
49	
50	impl TriggerHandle {
51	    /// Create a handle and its paired receiver (passed to `CrawlEngine::spawn`).
52	    pub fn new() -> (Self, tokio::sync::watch::Receiver<()>) {
53	        let (tx, rx) = tokio::sync::watch::channel(());
54	        (Self { tx }, rx)
55	    }
56	
57	    /// Send a wake signal to the engine.
58	    pub fn notify(&self) {
59	        let _ = self.tx.send(());
60	    }
61	}
62	
63	// ── Engine ────────────────────────────────────────────────────────────────────
64	
65	pub struct CrawlEngine {
66	    pool:      PgPool,
67	    semaphore: Arc<Semaphore>,
68	}
69	
70	impl CrawlEngine {
71	    /// Create a new engine. `max_workers` bounds concurrent crawl workers.
72	    pub fn new(pool: PgPool, max_workers: usize) -> Self {
73	        Self {
74	            pool,
75	            semaphore: Arc::new(Semaphore::new(max_workers.max(1))),
76	        }
77	    }
78	
79	    /// Spawn the engine as a background task.
80	    ///
81	    /// The engine wakes either on its 60-second tick or when the
82	    /// `trigger_rx` channel receives a value.
83	    pub fn spawn(self, mut trigger_rx: tokio::sync::watch::Receiver<()>) {
84	        tokio::spawn(async move {
85	            let mut tick = interval(Duration::from_secs(60));
86	            tick.set_missed_tick_behavior(MissedTickBehavior::Skip);
87	
88	            info!(
89	                max_workers = self.semaphore.available_permits(),
90	                "CrawlEngine started"
91	            );
92	
93	            loop {
94	                tokio::select! {
95	                    _ = tick.tick()          => {}
96	                    _ = trigger_rx.changed() => {
97	                        info!("CrawlEngine woken by trigger");
98	                    }
99	                }
100	                self.dispatch_due_tasks().await;
101	            }
102	        });
103	    }
104	
105	    async fn dispatch_due_tasks(&self) {
106	        let due = match CrawlTaskRepo::new(&self.pool).list_due().await {
107	            Ok(v)  => v,
108	            Err(e) => {
109	                error!(error = %e, "Failed to query due crawl tasks");
110	                return;
111	            }
112	        };
113	
114	        if due.is_empty() { return; }
115	        info!(count = due.len(), "Dispatching due crawl tasks");
116	
117	        for task in due {
118	            let permit = match self.semaphore.clone().try_acquire_owned() {
119	                Ok(p)  => p,
120	                Err(_) => {
121	                    warn!(task_id = %task.id, "Concurrency limit reached; deferring task");
122	                    break;
123	                }
124	            };
125	
126	            let pool = self.pool.clone();
127	            tokio::spawn(async move {
128	                let _permit = permit; // held until worker finishes
129	                run_task(pool, task).await;
130	            });
131	        }
132	    }
133	}
134	
135	// ── Worker ────────────────────────────────────────────────────────────────────
136	
137	async fn run_task(pool: PgPool, task: CrawlTask) {
138	    info!(task_id = %task.id, task_name = %task.task_name, "Crawl worker started");
139	
140	    if let Err(e) = CrawlTaskRepo::new(&pool).set_running(task.id).await {
141	        error!(task_id = %task.id, error = %e, "Failed to mark task running");
142	        return;
143	    }
144	
145	    let run_id = match CrawlRunRepo::new(&pool).start(task.id).await {
146	        Ok(id) => id,
147	        Err(e) => {
148	            error!(task_id = %task.id, error = %e, "Failed to start crawl run");
149	            let _ = CrawlTaskRepo::new(&pool).set_failed(task.id).await;
150	            return;
151	        }
152	    };
153	
154	    let source = match CrawlSourceRepo::new(&pool).find_by_id(task.source_id).await {
155	        Ok(Some(s)) => s,
156	        Ok(None) => {
157	            error!(source_id = %task.source_id, "Source not found");
158	            abort(&pool, run_id, task.id, "source not found").await;
159	            return;
160	        }
161	        Err(e) => {
162	            error!(error = %e, "Failed to load crawl source");
163	            abort(&pool, run_id, task.id, &e.to_string()).await;
164	            return;
165	        }
166	    };
167	
168	    let reader = reader_for(&source.source_type);
169	    let mut cursor = if task.incremental { task.resume_cursor.clone() } else { None };
170	
171	    let mut pages_fetched    : i32 = 0;
172	    let mut items_ingested   : i32 = 0;
173	    let mut items_quarantined: i32 = 0;
174	    let mut error_log: Option<String> = None;
175	
176	    // ── Page loop ─────────────────────────────────────────────────────────
177	    loop {
178	        let (raw_items, next_cursor) = match reader.read_page(&source, cursor.clone()).await {
179	            Ok(v)  => v,
180	            Err(e) => { warn!(error = %e, "Reader error"); error_log = Some(e); break; }
181	        };
182	
183	        pages_fetched += 1;
184	
185	        // Per-source rate limiting: sleep to enforce configured rate_limit_rps
186	        let delay_ms = (1000.0 / source.rate_limit_rps.to_string().parse::<f64>().unwrap_or(2.0)) as u64;
187	        if delay_ms > 0 {
188	            tokio::time::sleep(Duration::from_millis(delay_ms)).await;
189	        }
190	
191	        if raw_items.is_empty() { cursor = None; break; }
192	
193	        let mut page_ingested    = 0i32;
194	        let mut page_quarantined = 0i32;
195	
196	        for raw in &raw_items {
197	            let Some(transformed) = pipeline::transform(raw) else {
198	                warn!("Skipping untransformable item");
199	                continue;
200	            };
201	
202	            // Skip exact fingerprint duplicates.
203	            match ContentRepo::new(&pool).find_by_fingerprint(&transformed.fingerprint).await {
204	                Ok(Some(_)) => {
205	                    info!(fp = %transformed.fingerprint, "Duplicate — skipping");
206	                    continue;
207	                }
208	                Ok(None) => {}
209	                Err(e) => warn!(error = %e, "Fingerprint check failed"),
210	            }
211	
212	            let scored = match QualityScorer::score(&transformed, &pool, None).await {
213	                Ok(s)  => s,
214	                Err(e) => { warn!(error = %e, "Quality scoring failed"); continue; }
215	            };
216	
217	            let q = &scored.score;
218	
219	            let quality_log = NewQualityLog {
220	                crawl_run_id:         Some(run_id),
221	                content_id:           None,
222	                url_fingerprint:      Some(transformed.fingerprint.clone()),
223	                completeness_score:   Some(q.completeness),
224	                accuracy_score:       Some(q.accuracy),
225	                timeliness_score:     Some(q.timeliness),
226	                quality_score:        Some(q.total),
227	                issues:               Some(json!(scored.issues)),
228	                is_quarantined:       scored.is_quarantined,
229	                quarantine_reason:    scored.quarantine_reason.clone(),
230	                transformation_steps: Some(json!(transformed.transformation_steps)),
231	            };
232	
233	            if scored.is_quarantined {
234	                let _ = QualityRepo::new(&pool).insert(&quality_log).await;
235	                page_quarantined += 1;
236	                continue;
237	            }
238	
239	            let slug = make_unique_slug(&pool, &transformed.slug).await;
240	            let cmd = CreateContent {
241	                slug,
242	                title:              transformed.title.clone(),
243	                body:               transformed.body.clone(),
244	                category:           transformed.category.clone(),
245	                route_id:           None,
246	                publish_date:       transformed.publish_date,
247	                source_url:         transformed.source_url.clone(),
248	                source_fingerprint: Some(transformed.fingerprint.clone()),
249	                quality_score:      Some(q.total),
250	                tags:               transformed.tags.clone(),
251	            };
252	
253	            match ContentRepo::new(&pool).create(&cmd).await {
254	                Ok(content_id) => {
255	                    // Record quality log with content_id linked.
256	                    let mut linked = quality_log;
257	                    linked.content_id = Some(content_id);
258	                    let _ = QualityRepo::new(&pool).insert(&linked).await;
259	
260	                    // Auto-publish if quality is sufficient.
261	                    if q.is_publishable() {
262	                        let _ = ContentRepo::new(&pool).publish(content_id).await;
263	                    }
264	
265	                    // Sampling-based review: mark ~2% of items for manual review
266	                    let sample_pct: f64 = crate::domain::rules::repo::BusinessRuleRepo::new(&pool)
267	                        .get_value("sample_review_pct", "0.02")
268	                        .await
269	                        .parse()
270	                        .unwrap_or(0.02);
271	                    if rand::random::<f64>() < sample_pct {
272	                        let _ = sqlx::query(
273	                            "UPDATE quality_logs SET sampled_for_review = TRUE
274	                             WHERE content_id = $1
275	                             ORDER BY created_at DESC LIMIT 1"
276	                        )
277	                        .bind(content_id)
278	                        .execute(&pool)
279	                        .await;
280	                        info!(content_id = %content_id, "Sampled for review");
281	                    }
282	
283	                    page_ingested += 1;
284	                }
285	                Err(e) => {
286	                    warn!(error = %e, slug = %cmd.slug, "Failed to ingest content");
287	                    let _ = QualityRepo::new(&pool).insert(&quality_log).await;
288	                }
289	            }
290	        }
291	
292	        items_ingested    += page_ingested;
293	        items_quarantined += page_quarantined;
294	
295	        let _ = CrawlRunRepo::new(&pool)
296	            .increment_counters(run_id, 1, page_ingested, page_quarantined)
297	            .await;
298	
299	        cursor = next_cursor;
300	        if cursor.is_none() { break; }
301	    }
302	
303	    // ── Finish run ────────────────────────────────────────────────────────
304	    let status = if error_log.is_some() { "failed" } else { "completed" };
305	
306	    if let Err(e) = CrawlRunRepo::new(&pool)
307	        .finish(run_id, status, pages_fetched, items_ingested, items_quarantined, error_log.as_deref())
308	        .await
309	    {
310	        error!(run_id = %run_id, error = %e, "Failed to finish crawl run");
311	    }
312	
313	    let next_crawl = Some(Utc::now() + chrono::Duration::hours(1));
314	    if let Err(e) = CrawlTaskRepo::new(&pool).complete(task.id, cursor, next_crawl).await {
315	        error!(task_id = %task.id, error = %e, "Failed to complete crawl task");
316	    }
317	
318	    info!(
319	        task_id     = %task.id,
320	        run_id      = %run_id,
321	        ingested    = items_ingested,
322	        quarantined = items_quarantined,
323	        status      = status,
324	        "Crawl worker finished"
325	    );
326	}
