1	//! Source readers for the offline collection engine.
2	//!
3	//! All source types in this project are **offline** (file-system based).
4	//! Readers implement the [`SourceReader`] trait and return up to `PAGE_SIZE`
5	//! items per call together with a resumption cursor.
6	//!
7	//! ## Cursor format (JSON)
8	//!
9	//! ```json
10	//! { "file_index": 3, "item_offset": 12 }
11	//! ```
12	//!
13	//! - `file_index`  — 0-based index into the sorted list of `.json` files under
14	//!                   the source's `base_path`.
15	//! - `item_offset` — 0-based position within that file's item array.
16	//!
17	//! `None` next-cursor signals the source is exhausted for this run.
18	
19	use std::path::Path;
20	
21	use async_trait::async_trait;
22	use serde::{Deserialize, Serialize};
23	use serde_json::Value;
24	use tracing::{debug, warn};
25	
26	use super::pipeline::RawItem;
27	use crate::domain::crawl::models::CrawlSource;
28	
29	const PAGE_SIZE: usize = 50;
30	
31	// ── Cursor ────────────────────────────────────────────────────────────────────
32	
33	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
34	pub struct FileCursor {
35	    pub file_index:  usize,
36	    pub item_offset: usize,
37	}
38	
39	impl FileCursor {
40	    pub fn from_value(v: &Value) -> Self {
41	        serde_json::from_value(v.clone()).unwrap_or_default()
42	    }
43	
44	    pub fn to_value(&self) -> Value {
45	        serde_json::to_value(self).unwrap_or(Value::Null)
46	    }
47	}
48	
49	// ── Trait ─────────────────────────────────────────────────────────────────────
50	
51	/// Yields pages of raw items from an underlying data source.
52	#[async_trait]
53	pub trait SourceReader: Send + Sync {
54	    async fn read_page(
55	        &self,
56	        source: &CrawlSource,
57	        cursor: Option<Value>,
58	    ) -> Result<(Vec<RawItem>, Option<Value>), String>;
59	}
60	
61	// ── LocalPackageReader ────────────────────────────────────────────────────────
62	
63	/// Reads JSON packages from `source.base_path`.
64	///
65	/// Each `.json` file must be either a JSON array of objects or a single object.
66	pub struct LocalPackageReader;
67	
68	#[async_trait]
69	impl SourceReader for LocalPackageReader {
70	    async fn read_page(
71	        &self,
72	        source: &CrawlSource,
73	        cursor: Option<Value>,
74	    ) -> Result<(Vec<RawItem>, Option<Value>), String> {
75	        let base = source
76	            .base_path
77	            .as_deref()
78	            .ok_or_else(|| "LocalPackageReader: source has no base_path".to_owned())?;
79	
80	        read_from_dir(base, cursor).await
81	    }
82	}
83	
84	// ── InternalMirrorReader ──────────────────────────────────────────────────────
85	
86	/// Reads JSON packages from `{source.base_path}/mirror/`.
87	pub struct InternalMirrorReader;
88	
89	#[async_trait]
90	impl SourceReader for InternalMirrorReader {
91	    async fn read_page(
92	        &self,
93	        source: &CrawlSource,
94	        cursor: Option<Value>,
95	    ) -> Result<(Vec<RawItem>, Option<Value>), String> {
96	        let base = source
97	            .base_path
98	            .as_deref()
99	            .ok_or_else(|| "InternalMirrorReader: source has no base_path".to_owned())?;
100	
101	        let mirror = format!("{base}/mirror");
102	        read_from_dir(&mirror, cursor).await
103	    }
104	}
105	
106	// ── Shared implementation ─────────────────────────────────────────────────────
107	
108	async fn read_from_dir(
109	    dir:    &str,
110	    cursor: Option<Value>,
111	) -> Result<(Vec<RawItem>, Option<Value>), String> {
112	    let path = Path::new(dir);
113	    let mut files = collect_json_files(path).await
114	        .map_err(|e| format!("Cannot read directory '{dir}': {e}"))?;
115	
116	    files.sort(); // deterministic order across runs
117	
118	    if files.is_empty() {
119	        return Ok((Vec::new(), None));
120	    }
121	
122	    let cur = cursor.as_ref().map(FileCursor::from_value).unwrap_or_default();
123	    let mut file_idx = cur.file_index;
124	    let mut item_off = cur.item_offset;
125	    let mut collected: Vec<RawItem> = Vec::with_capacity(PAGE_SIZE);
126	
127	    while collected.len() < PAGE_SIZE && file_idx < files.len() {
128	        let file_path = &files[file_idx];
129	        debug!(file = %file_path.display(), "Reading source file");
130	
131	        let bytes = tokio::fs::read(file_path)
132	            .await
133	            .map_err(|e| format!("Cannot read '{}': {e}", file_path.display()))?;
134	
135	        let json: Value = serde_json::from_slice(&bytes)
136	            .map_err(|e| format!("JSON parse error in '{}': {e}", file_path.display()))?;
137	
138	        let items_json: Vec<Value> = match json {
139	            Value::Array(arr)  => arr,
140	            obj @ Value::Object(_) => vec![obj],
141	            _ => {
142	                warn!(file = %file_path.display(), "Unexpected JSON root type — skipping");
143	                file_idx += 1;
144	                item_off  = 0;
145	                continue;
146	            }
147	        };
148	
149	        let remaining = PAGE_SIZE - collected.len();
150	        let start     = item_off.min(items_json.len());
151	        let end       = (start + remaining).min(items_json.len());
152	
153	        for v in &items_json[start..end] {
154	            match serde_json::from_value::<RawItem>(v.clone()) {
155	                Ok(item)  => collected.push(item),
156	                Err(e)    => warn!("Skipping malformed item: {e}"),
157	            }
158	        }
159	
160	        item_off = end;
161	        if item_off >= items_json.len() {
162	            file_idx += 1;
163	            item_off  = 0;
164	        }
165	    }
166	
167	    let next_cursor = if file_idx < files.len() {
168	        Some(FileCursor { file_index: file_idx, item_offset: item_off }.to_value())
169	    } else {
170	        None
171	    };
172	
173	    Ok((collected, next_cursor))
174	}
175	
176	/// Collect all `.json` file paths in a directory (non-recursive).
177	async fn collect_json_files(dir: &Path) -> std::io::Result<Vec<std::path::PathBuf>> {
178	    let mut read_dir = tokio::fs::read_dir(dir).await?;
179	    let mut paths    = Vec::new();
180	
181	    while let Some(entry) = read_dir.next_entry().await? {
182	        let p = entry.path();
183	        if p.extension().map(|x| x.eq_ignore_ascii_case("json")).unwrap_or(false) {
184	            paths.push(p);
185	        }
186	    }
187	
188	    Ok(paths)
189	}
190	
191	// ── Factory ───────────────────────────────────────────────────────────────────
192	
193	/// Return the appropriate `SourceReader` for the given `source_type` string.
194	pub fn reader_for(source_type: &str) -> Box<dyn SourceReader> {
195	    match source_type {
196	        "internal_mirror" => Box::new(InternalMirrorReader),
197	        _                 => Box::new(LocalPackageReader),
198	    }
199	}
