417	/// Process a refund for a cancelled order.
418	///
419	/// The allowed refund amount is computed by `RulesEngine::evaluate_refund`,
420	/// which applies live-configurable tiered logic:
421	///
422	///   - > `refund_full_hours` before departure  → FullMinusFee
423	///   - 2–24 h before departure                → HalfFare
424	///   - < `refund_partial_hours` + disruption  → ServiceDisruption (full fare)
425	///   - < `refund_partial_hours`, no disruption → blocked (HTTP 422)
426	///
427	/// The caller may submit any amount ≤ the computed maximum; the maximum
428	/// is always returned in the response for UI display.
429	pub async fn process_refund(
430	    pool:  web::Data<PgPool>,
431	    path:  web::Path<Uuid>,
432	    body:  web::Json<RefundBody>,
433	    auth:  RequireProcessRefunds,
434	) -> AppResult<HttpResponse> {
435	    let id    = path.into_inner();
436	    // Use find_detail to get departure_time and disruption_flag in one query.
437	    let order = OrderRepo::new(&pool)
438	        .find_detail(id)
439	        .await?
440	        .ok_or_else(|| AppError::NotFound("Order".into()))?;
441	
442	    if order.status != "cancelled" {
443	        return Err(AppError::Validation(
444	            "Refunds can only be processed for cancelled orders".into(),
445	        ));
446	    }
447	    if body.amount <= Decimal::ZERO {
448	        return Err(AppError::Validation("Refund amount must be positive".into()));
449	    }
450	
451	    // Policy evaluation — may return RefundBlocked.
452	    let decision = RulesEngine::new(&pool)
453	        .evaluate_refund(order.departure_time, order.fare_amount, order.disruption_flag)
454	        .await?;
455	
456	    if body.amount > decision.max_amount {
457	        return Err(AppError::RefundBlocked(format!(
458	            "Requested ${} exceeds the ${} maximum for outcome {:?} — {}",
459	            body.amount, decision.max_amount, decision.outcome, decision.reason,
460	        )));
461	    }
462	
463	    OrderRepo::new(&pool).set_refunded(id, body.amount).await?;
