            // Departed within 7 days: moderate penalty (old but perhaps still useful).
            let days_past = (today - dep_date).num_days();
            if days_past > 7 {
                penalty += 90.0; // ensures score falls below publishable threshold
            } else {
                penalty += 40.0;
            }
        }
    }

    penalty
}"}

