2	//!
3	//! Accepts a `RawItem` (JSON-deserialized from a source file) and produces a
4	//! `TransformedItem` suitable for ingestion into `content_pages`.
5	//!
6	//! Transformation steps (recorded in `transformation_steps`):
7	//!   1. strip_html  — remove all HTML tags via a simple state machine
8	//!   2. normalize   — collapse whitespace (spaces, tabs, newlines) to single space
9	//!   3. trim        — strip leading/trailing whitespace
10	//!   4. abbreviate  — expand common railway abbreviations
11	//!   5. fingerprint — SHA-256 hex of `title‖body‖source_url`
12	//!   6. slugify     — URL-safe slug from title
13	
14	use chrono::NaiveDate;
15	use serde::{Deserialize, Serialize};
16	use sha2::{Digest, Sha256};
17	
18	// ── Input ─────────────────────────────────────────────────────────────────────
19	
20	/// Raw, uncleaned record as read from a source JSON file.
21	#[derive(Debug, Clone, Deserialize)]
22	pub struct RawItem {
23	    pub title:          Option<String>,
24	    pub body:           Option<String>,
25	    pub category:       Option<String>,
26	    pub tags:           Option<Vec<String>>,
27	    pub publish_date:   Option<String>,
28	    pub source_url:     Option<String>,
29	    pub author:         Option<String>,
30	    pub image_url:      Option<String>,
31	    /// Optional departure date for route/schedule-linked articles (YYYY-MM-DD).
32	    /// Used to detect "departure in the past" anomalies during quality scoring.
33	    pub departure_date: Option<String>,
34	}
35	
36	// ── Output ────────────────────────────────────────────────────────────────────
37	
38	/// Validated, cleaned record ready for the quality scorer and DB ingest.
39	#[derive(Debug, Clone, Serialize)]
40	pub struct TransformedItem {
41	    pub title:                String,
42	    pub slug:                 String,
43	    pub body:                 String,
44	    pub category:             String,
45	    pub tags:                 Vec<String>,
46	    pub publish_date:         Option<NaiveDate>,
47	    pub source_url:           Option<String>,
48	    pub author:               Option<String>,
49	    pub image_url:            Option<String>,
50	    pub fingerprint:          String,
51	    pub url_fingerprint:      Option<String>,
52	    pub transformation_steps: Vec<String>,
53	    /// Parsed departure date from source data — used for anomaly detection.
54	    pub departure_date:       Option<NaiveDate>,
55	}
56	
57	// ── Transform ─────────────────────────────────────────────────────────────────
58	
59	/// Transform a `RawItem` into a `TransformedItem`.
60	/// Returns `None` if the item has neither a usable title nor body.
61	pub fn transform(raw: &RawItem) -> Option<TransformedItem> {
62	    let mut steps: Vec<String> = Vec::new();
63	
64	    let title = apply_text_pipeline(raw.title.as_deref().unwrap_or(""), &mut steps, "title");
65	    let body  = apply_text_pipeline(raw.body.as_deref().unwrap_or(""),  &mut steps, "body");
66	
67	    if title.is_empty() && body.is_empty() {
68	        return None;
69	    }
70	
71	    let category = raw
72	        .category
73	        .as_deref()
74	        .map(|c| c.to_lowercase())
75	        .filter(|c| matches!(c.as_str(), "fares" | "delays" | "baggage" | "accessibility"))
76	        .unwrap_or_else(|| "general".to_owned());
77	
78	    let tags: Vec<String> = raw
79	        .tags
80	        .as_deref()
81	        .unwrap_or(&[])
82	        .iter()
83	        .map(|t| t.trim().to_lowercase())
84	        .filter(|t| !t.is_empty())
85	        .collect();
86	
87	    let publish_date = raw.publish_date.as_deref().and_then(|s| {
88	        NaiveDate::parse_from_str(s, "%Y-%m-%d")
89	            .or_else(|_| NaiveDate::parse_from_str(s, "%d/%m/%Y"))
90	            .or_else(|_| NaiveDate::parse_from_str(s, "%m/%d/%Y"))
91	            .ok()
92	    });
93	
94	    let departure_date = raw.departure_date.as_deref().and_then(|s| {
95	        NaiveDate::parse_from_str(s, "%Y-%m-%d")
96	            .or_else(|_| NaiveDate::parse_from_str(s, "%d/%m/%Y"))
97	            .ok()
98	    });
99	
100	    let slug_source = if !title.is_empty() {
101	        title.as_str()
102	    } else {
103	        &body[..body.len().min(80)]
104	    };
105	    let slug = slugify(slug_source);
106	    steps.push("slugify".to_owned());
107	
108	    let fingerprint = content_fingerprint(&title, &body, raw.source_url.as_deref());
109	    steps.push("fingerprint".to_owned());
110	
111	    // Dedicated URL-only fingerprint for source-URL-based deduplication.
112	    let url_fingerprint = raw.source_url.as_deref().map(url_fingerprint);
113	
114	    Some(TransformedItem {
115	        title,
116	        slug,
117	        body,
118	        category,
119	        tags,
120	        publish_date,
121	        source_url:           raw.source_url.clone(),
122	        author:               raw.author.clone(),
123	        image_url:            raw.image_url.clone(),
124	        fingerprint,
125	        url_fingerprint,
126	        transformation_steps: steps,
127	        departure_date,
128	    })
129	}
130	
131	// ── Text pipeline ─────────────────────────────────────────────────────────────
132	
133	fn apply_text_pipeline(input: &str, steps: &mut Vec<String>, label: &str) -> String {
134	    let stripped = strip_html(input);
135	    if stripped != input { steps.push(format!("strip_html:{label}")); }
136	
137	    let normalized = normalize_whitespace(&stripped);
138	    if normalized != stripped { steps.push(format!("normalize:{label}")); }
139	
140	    let trimmed = normalized.trim().to_owned();
141	    if trimmed != normalized { steps.push(format!("trim:{label}")); }
142	
143	    let expanded = expand_abbreviations(&trimmed);
144	    if expanded != trimmed { steps.push(format!("abbreviate:{label}")); }
145	
146	    expanded
147	}
148	
149	/// Remove HTML/XML tags with a simple state machine, replacing each tag with
150	/// a single space to prevent adjacent words from merging.
151	fn strip_html(input: &str) -> String {
152	    let mut out = String::with_capacity(input.len());
153	    let mut in_tag = false;
154	
155	    for ch in input.chars() {
156	        match ch {
157	            '<' => { in_tag = true; }
158	            '>' => {
159	                in_tag = false;
160	                out.push(' ');
161	            }
162	            _ if !in_tag => out.push(ch),
163	            _ => {}
164	        }
165	    }
166	    out
167	}
168	
169	/// Collapse any run of ASCII whitespace to a single space.
170	fn normalize_whitespace(input: &str) -> String {
171	    let mut out = String::with_capacity(input.len());
172	    let mut prev_space = false;
173	
174	    for ch in input.chars() {
175	        if ch.is_ascii_whitespace() {
176	            if !prev_space { out.push(' '); }
177	            prev_space = true;
178	        } else {
179	            out.push(ch);
180	            prev_space = false;
181	        }
182	    }
183	    out
184	}
185	
186	/// Expand a small set of unambiguous railway-domain abbreviations.
187	fn expand_abbreviations(input: &str) -> String {
188	    const ABBREVS: &[(&str, &str)] = &[
189	        ("dept.", "department"),
190	        ("stn.",  "station"),
191	        ("arr.",  "arrival"),
192	        ("dep.",  "departure"),
193	        ("approx.", "approximately"),
194	        ("min.",  "minutes"),
195	        ("hr.",   "hours"),
196	    ];
197	
198	    let mut s = input.to_owned();
199	    for (abbr, expansion) in ABBREVS {
200	        // Replace all literal occurrences of the abbreviation (case-sensitive, lowercase).
201	        let mut pos = 0;
202	        while let Some(found) = s[pos..].find(abbr) {
203	            let abs = pos + found;
204	            s.replace_range(abs..abs + abbr.len(), expansion);
205	            pos = abs + expansion.len();
206	        }
207	    }
208	    s
209	}
210	
211	// ── Fingerprint ───────────────────────────────────────────────────────────────
212	
213	/// SHA-256 fingerprint for deduplication (stable across identical content).
214	pub fn content_fingerprint(title: &str, body: &str, source_url: Option<&str>) -> String {
215	    let mut h = Sha256::new();
216	    h.update(title.as_bytes());
217	    h.update(b"\x00");
218	    h.update(body.as_bytes());
219	    h.update(b"\x00");
220	    if let Some(url) = source_url { h.update(url.as_bytes()); }
221	    hex::encode(h.finalize())
222	}
223	
224	/// SHA-256 fingerprint of the source URL alone (normalized: trimmed + lowercase scheme+host).
225	///
226	/// This is used as a first-class URL-based dedup signal: two articles from the
227	/// same canonical URL are treated as duplicates regardless of title/body changes.
228	pub fn url_fingerprint(source_url: &str) -> String {
229	    // Minimal normalization: trim whitespace, lowercase the scheme and host portion.
230	    let normalized = source_url.trim();
231	    let normalized = if let Some(rest) = normalized.strip_prefix("HTTPS://")
232	        .or_else(|| normalized.strip_prefix("HTTP://"))
233	    {
234	        // Reconstruct with lower-cased scheme.
235	        let scheme = if normalized.to_ascii_lowercase().starts_with("https") { "https" } else { "http" };
236	        format!("{scheme}://{rest}")
237	    } else {
238	        normalized.to_owned()
239	    };
240	    let mut h = Sha256::new();
241	    h.update(normalized.as_bytes());
242	    hex::encode(h.finalize())
243	}
244	
245	// ── Slug ──────────────────────────────────────────────────────────────────────
246	
247	/// Convert free-form text to a URL-safe, hyphen-separated slug (max 120 chars).
248	pub fn slugify(input: &str) -> String {
249	    let mut slug = String::with_capacity(input.len().min(130));
250	    let mut prev_hyphen = true; // suppress leading hyphens
251	
252	    for ch in input.chars() {
253	        if ch.is_alphanumeric() {
254	            slug.push(ch.to_ascii_lowercase());
255	            prev_hyphen = false;
256	        } else if !prev_hyphen {
257	            slug.push('-');
258	            prev_hyphen = true;
259	        }
260	    }
261	
262	    if slug.ends_with('-') { slug.pop(); }
263	
264	    if slug.len() > 120 {
265	        let cut = slug[..120].rfind('-').unwrap_or(120);
266	        slug.truncate(cut);
267	    }
268	
269	    slug
270	}
