1	//! Background crawl engine.
2	//!
3	//! [`CrawlEngine`] runs as a long-lived tokio task that wakes every 60 seconds
4	//! (or immediately when triggered via the [`TriggerHandle`]), queries the DB
5	//! for due tasks, and spawns a bounded worker per task.
6	//!
7	//! ## Worker lifecycle
8	//!
9	//! ```text
10	//! list_due() → [task₁, task₂, …]
11	//!   for each task (bounded by Semaphore):
12	//!     set_running(task)
13	//!     run_id = CrawlRunRepo::start()
14	//!     loop {
15	//!       read_page(cursor) → (items, next_cursor)
16	//!       for each item:
17	//!         transform → fingerprint-dedup → score → ingest / quarantine
18	//!       increment_counters
19	//!       cursor = next_cursor or break if None
20	//!     }
21	//!     CrawlRunRepo::finish()
22	//!     CrawlTaskRepo::complete(cursor, next_crawl_at)
23	//! ```
24	
25	use std::sync::Arc;
26	
27	use chrono::Utc;
28	use serde_json::json;
29	use sqlx::PgPool;
30	use tokio::sync::Semaphore;
31	use tokio::time::{interval, Duration, MissedTickBehavior};
32	use tracing::{error, info, warn};
33	
34	use crate::domain::content::models::CreateContent;
35	use crate::domain::content::repo::ContentRepo;
36	use crate::domain::crawl::models::{CrawlTask, NewQualityLog};
37	use crate::domain::crawl::repo::{CrawlRunRepo, CrawlSourceRepo, CrawlTaskRepo, QualityRepo};
38	
39	use super::pipeline;
40	use super::quality::QualityScorer;
41	use super::reader::reader_for;
42	
43	// ── Trigger handle ────────────────────────────────────────────────────────────
44	
45	/// Allows HTTP handlers to wake the engine without waiting for the next tick.
46	pub struct TriggerHandle {
47	    tx: tokio::sync::watch::Sender<()>,
48	}
49	
50	impl TriggerHandle {
51	    /// Create a handle and its paired receiver (passed to `CrawlEngine::spawn`).
52	    pub fn new() -> (Self, tokio::sync::watch::Receiver<()>) {
53	        let (tx, rx) = tokio::sync::watch::channel(());
54	        (Self { tx }, rx)
55	    }
56	
57	    /// Send a wake signal to the engine.
58	    pub fn notify(&self) {
59	        let _ = self.tx.send(());
60	    }
61	}
62	
63	// ── Engine ────────────────────────────────────────────────────────────────────
64	
65	pub struct CrawlEngine {
66	    pool:      PgPool,
67	    semaphore: Arc<Semaphore>,
68	}
69	
70	impl CrawlEngine {
71	    /// Create a new engine. `max_workers` bounds concurrent crawl workers.
72	    pub fn new(pool: PgPool, max_workers: usize) -> Self {
73	        Self {
74	            pool,
75	            semaphore: Arc::new(Semaphore::new(max_workers.max(1))),
76	        }
77	    }
78	
79	    /// Spawn the engine as a background task.
80	    ///
81	    /// The engine wakes either on its 60-second tick or when the
82	    /// `trigger_rx` channel receives a value.
83	    pub fn spawn(self, mut trigger_rx: tokio::sync::watch::Receiver<()>) {
84	        tokio::spawn(async move {
85	            let mut tick = interval(Duration::from_secs(60));
86	            tick.set_missed_tick_behavior(MissedTickBehavior::Skip);
87	
88	            info!(
89	                max_workers = self.semaphore.available_permits(),
90	                "CrawlEngine started"
91	            );
92	
93	            loop {
94	                tokio::select! {
95	                    _ = tick.tick()          => {}
96	                    _ = trigger_rx.changed() => {
97	                        info!("CrawlEngine woken by trigger");
98	                    }
99	                }
100	                self.dispatch_due_tasks().await;
101	            }
102	        });
103	    }
104	
105	    async fn dispatch_due_tasks(&self) {
106	        let due = match CrawlTaskRepo::new(&self.pool).list_due().await {
107	            Ok(v)  => v,
108	            Err(e) => {
109	                error!(error = %e, "Failed to query due crawl tasks");
110	                return;
111	            }
112	        };
113	
114	        if due.is_empty() { return; }
115	        info!(count = due.len(), "Dispatching due crawl tasks");
116	
117	        for task in due {
118	            let permit = match self.semaphore.clone().try_acquire_owned() {
119	                Ok(p)  => p,
120	                Err(_) => {
121	                    warn!(task_id = %task.id, "Concurrency limit reached; deferring task");
122	                    break;
123	                }
124	            };
125	
126	            let pool = self.pool.clone();
127	            tokio::spawn(async move {
128	                let _permit = permit; // held until worker finishes
129	                run_task(pool, task).await;
130	            });
131	        }
132	    }
133	}
134	
135	// ── Worker ────────────────────────────────────────────────────────────────────
136	
137	async fn run_task(pool: PgPool, task: CrawlTask) {
138	    info!(task_id = %task.id, task_name = %task.task_name, "Crawl worker started");
139	
140	    if let Err(e) = CrawlTaskRepo::new(&pool).set_running(task.id).await {
141	        error!(task_id = %task.id, error = %e, "Failed to mark task running");
142	        return;
143	    }
144	
145	    let run_id = match CrawlRunRepo::new(&pool).start(task.id).await {
146	        Ok(id) => id,
147	        Err(e) => {
148	            error!(task_id = %task.id, error = %e, "Failed to start crawl run");
149	            let _ = CrawlTaskRepo::new(&pool).set_failed(task.id).await;
150	            return;
151	        }
152	    };
153	
154	    let source = match CrawlSourceRepo::new(&pool).find_by_id(task.source_id).await {
155	        Ok(Some(s)) => s,
156	        Ok(None) => {
157	            error!(source_id = %task.source_id, "Source not found");
158	            abort(&pool, run_id, task.id, "source not found").await;
159	            return;
160	        }
161	        Err(e) => {
162	            error!(error = %e, "Failed to load crawl source");
163	            abort(&pool, run_id, task.id, &e.to_string()).await;
164	            return;
165	        }
166	    };
167	
168	    let reader = reader_for(&source.source_type);
169	    let mut cursor = if task.incremental { task.resume_cursor.clone() } else { None };
170	
171	    // ── Resolve task-definition controls ─────────────────────────────────
172	    // city / keywords come from the source; pagination_rules from the task.
173	    let city_filter: Option<String> = source.city.as_ref()
174	        .map(|c| c.trim().to_lowercase())
175	        .filter(|c| !c.is_empty());
176	
177	    let keyword_filters: Vec<String> = source.keywords.iter()
178	        .map(|k| k.trim().to_lowercase())
179	        .filter(|k| !k.is_empty())
180	        .collect();
181	
182	    let max_pages: Option<i32> = task.pagination_rules
183	        .as_ref()
184	        .and_then(|v| v.get("max_pages"))
185	        .and_then(|v| v.as_i64())
186	        .map(|n| n.max(1) as i32);
187	
188	    let max_items: Option<i32> = task.pagination_rules
189	        .as_ref()
190	        .and_then(|v| v.get("max_items"))
191	        .and_then(|v| v.as_i64())
192	        .map(|n| n.max(1) as i32);
193	
194	    if let Some(city) = &city_filter {
195	        info!(task_id = %task.id, city = %city, "City filter active");
196	    }
197	    if !keyword_filters.is_empty() {
198	        info!(task_id = %task.id, keywords = ?keyword_filters, "Keyword filter active");
199	    }
200	    if let Some(mp) = max_pages {
201	        info!(task_id = %task.id, max_pages = mp, "Pagination limit active");
202	    }
203	
204	    let mut pages_fetched    : i32 = 0;
205	    let mut items_ingested   : i32 = 0;
206	    let mut items_quarantined: i32 = 0;
207	    let mut error_log: Option<String> = None;
208	
209	    // ── Page loop ─────────────────────────────────────────────────────────
210	    loop {
211	        // Enforce max_pages from pagination_rules.
212	        if let Some(mp) = max_pages {
213	            if pages_fetched >= mp {
214	                info!(task_id = %task.id, "Reached max_pages={mp} — stopping");
215	                break;
216	            }
217	        }
218	
219	        let (raw_items, next_cursor) = match reader.read_page(&source, cursor.clone()).await {
220	            Ok(v)  => v,
221	            Err(e) => { warn!(error = %e, "Reader error"); error_log = Some(e); break; }
222	        };
223	
224	        pages_fetched += 1;
225	
226	        // Per-source rate limiting: sleep to enforce configured rate_limit_rps
227	        let delay_ms = (1000.0 / source.rate_limit_rps.to_string().parse::<f64>().unwrap_or(2.0)) as u64;
228	        if delay_ms > 0 {
229	            tokio::time::sleep(Duration::from_millis(delay_ms)).await;
230	        }
231	
232	        if raw_items.is_empty() { cursor = None; break; }
233	
234	        let mut page_ingested    = 0i32;
235	        let mut page_quarantined = 0i32;
236	        let mut stop_after_page  = false; // set true when max_items is reached
237	
238	        for raw in &raw_items {
239	            // Enforce max_items from pagination_rules.
240	            if let Some(mi) = max_items {
241	                if items_ingested + page_ingested >= mi {
242	                    info!(task_id = %task.id, "Reached max_items={mi} — stopping");
243	                    stop_after_page = true;
244	                    break;
245	                }
246	            }
247	
248	            let Some(transformed) = pipeline::transform(raw) else {
249	                warn!("Skipping untransformable item");
250	                continue;
251	            };
252	
253	            // ── City filter ───────────────────────────────────────────────
254	            // If the source has a city constraint, only ingest items that
255	            // mention the city in title, body, or tags (case-insensitive).
256	            if let Some(city) = &city_filter {
257	                let haystack = format!(
258	                    "{} {} {}",
259	                    transformed.title.to_lowercase(),
260	                    transformed.body.to_lowercase(),
261	                    transformed.tags.join(" ").to_lowercase(),
262	                );
263	                if !haystack.contains(city.as_str()) {
264	                    info!(city = %city, "Skipping item — city filter not matched");
265	                    continue;
266	                }
267	            }
268	
269	            // ── Keyword filter ────────────────────────────────────────────
270	            // If the source has keyword constraints, at least one keyword
271	            // must appear in the title or body (case-insensitive).
272	            if !keyword_filters.is_empty() {
273	                let haystack = format!(
274	                    "{} {}",
275	                    transformed.title.to_lowercase(),
276	                    transformed.body.to_lowercase(),
277	                );
278	                let any_match = keyword_filters.iter()
279	                    .any(|kw| haystack.contains(kw.as_str()));
280	                if !any_match {
281	                    info!(keywords = ?keyword_filters, "Skipping item — keyword filter not matched");
282	                    continue;
283	                }
284	            }
285	
286	            // ── Dedup: URL fingerprint (first-class) ──────────────────────
287	            // If a content page with the same source URL already exists,
288	            // skip re-ingest regardless of title/body changes.
289	            if let Some(ref url_fp) = transformed.url_fingerprint {
290	                match ContentRepo::new(&pool).find_by_url_fingerprint(url_fp).await {
291	                    Ok(Some(_)) => {
292	                        info!(url_fp = %url_fp, "URL duplicate — skipping");
293	                        continue;
294	                    }
295	                    Ok(None) => {}
296	                    Err(e) => warn!(error = %e, "URL fingerprint check failed"),
297	                }
298	            }
299	
300	            // ── Dedup: composite content fingerprint (exact match) ────────
301	            match ContentRepo::new(&pool).find_by_fingerprint(&transformed.fingerprint).await {
302	                Ok(Some(_)) => {
303	                    info!(fp = %transformed.fingerprint, "Content duplicate — skipping");
304	                    continue;
305	                }
306	                Ok(None) => {}
307	                Err(e) => warn!(error = %e, "Fingerprint check failed"),
308	            }
309	
310	            let scored = match QualityScorer::score(&transformed, &pool, None).await {
311	                Ok(s)  => s,
312	                Err(e) => { warn!(error = %e, "Quality scoring failed"); continue; }
313	            };
314	
315	            let q = &scored.score;
316	
317	            let quality_log = NewQualityLog {
318	                crawl_run_id:         Some(run_id),
319	                content_id:           None,
320	                url_fingerprint:      Some(transformed.fingerprint.clone()),
321	                completeness_score:   Some(q.completeness),
322	                accuracy_score:       Some(q.accuracy),
323	                timeliness_score:     Some(q.timeliness),
324	                quality_score:        Some(q.total),
325	                issues:               Some(json!(scored.issues)),
326	                is_quarantined:       scored.is_quarantined,
327	                quarantine_reason:    scored.quarantine_reason.clone(),
328	                transformation_steps: Some(json!(transformed.transformation_steps)),
329	            };
330	
331	            if scored.is_quarantined {
332	                let _ = QualityRepo::new(&pool).insert(&quality_log).await;
333	                page_quarantined += 1;
334	                continue;
335	            }
336	
337	            let slug = make_unique_slug(&pool, &transformed.slug).await;
338	            let cmd = CreateContent {
339	                slug,
340	                title:              transformed.title.clone(),
341	                body:               transformed.body.clone(),
342	                category:           transformed.category.clone(),
343	                route_id:           None,
344	                publish_date:       transformed.publish_date,
345	                source_url:         transformed.source_url.clone(),
346	                source_fingerprint: Some(transformed.fingerprint.clone()),
347	                url_fingerprint:    transformed.url_fingerprint.clone(),
348	                quality_score:      Some(q.total),
349	                tags:               transformed.tags.clone(),
350	            };
351	
352	            match ContentRepo::new(&pool).create(&cmd).await {
353	                Ok(content_id) => {
354	                    // Record quality log with content_id linked.
355	                    let mut linked = quality_log;
356	                    linked.content_id = Some(content_id);
357	                    let _ = QualityRepo::new(&pool).insert(&linked).await;
358	
359	                    // Auto-publish if quality is sufficient.
360	                    if q.is_publishable() {
361	                        let _ = ContentRepo::new(&pool).publish(content_id).await;
362	                    }
363	
364	                    // Sampling-based review: mark ~2% of items for manual review
365	                    let sample_pct: f64 = crate::domain::rules::repo::BusinessRuleRepo::new(&pool)
366	                        .get_value("sample_review_pct", "0.02")
367	                        .await
368	                        .parse()
369	                        .unwrap_or(0.02);
370	                    if rand::random::<f64>() < sample_pct {
371	                        let _ = sqlx::query(
372	                            "UPDATE quality_logs SET sampled_for_review = TRUE
373	                             WHERE content_id = $1
374	                             ORDER BY created_at DESC LIMIT 1"
375	                        )
376	                        .bind(content_id)
377	                        .execute(&pool)
378	                        .await;
379	                        info!(content_id = %content_id, "Sampled for review");
380	                    }
381	
382	                    page_ingested += 1;
383	                }
384	                Err(e) => {
385	                    warn!(error = %e, slug = %cmd.slug, "Failed to ingest content");
386	                    let _ = QualityRepo::new(&pool).insert(&quality_log).await;
387	                }
388	            }
389	        }
390	
391	        items_ingested    += page_ingested;
392	        items_quarantined += page_quarantined;
393	
394	        let _ = CrawlRunRepo::new(&pool)
395	            .increment_counters(run_id, 1, page_ingested, page_quarantined)
396	            .await;
397	
398	        if stop_after_page {
399	            cursor = None;
400	            break;
401	        }
402	
403	        cursor = next_cursor;
404	        if cursor.is_none() { break; }
405	    }
406	
407	    // ── Finish run ────────────────────────────────────────────────────────
408	    let status = if error_log.is_some() { "failed" } else { "completed" };
409	
410	    if let Err(e) = CrawlRunRepo::new(&pool)
411	        .finish(run_id, status, pages_fetched, items_ingested, items_quarantined, error_log.as_deref())
412	        .await
413	    {
414	        error!(run_id = %run_id, error = %e, "Failed to finish crawl run");
415	    }
416	
417	    let next_crawl = Some(Utc::now() + chrono::Duration::hours(1));
418	    if let Err(e) = CrawlTaskRepo::new(&pool).complete(task.id, cursor, next_crawl).await {
419	        error!(task_id = %task.id, error = %e, "Failed to complete crawl task");
420	    }
421	
422	    info!(
423	        task_id     = %task.id,
424	        run_id      = %run_id,
425	        ingested    = items_ingested,
426	        quarantined = items_quarantined,
427	        status      = status,
428	        "Crawl worker finished"
429	    );
430	}
431	
432	// ── Helpers ───────────────────────────────────────────────────────────────────
433	
434	async fn abort(pool: &PgPool, run_id: uuid::Uuid, task_id: uuid::Uuid, reason: &str) {
435	    let _ = CrawlRunRepo::new(pool)
436	        .finish(run_id, "failed", 0, 0, 0, Some(reason))
437	        .await;
438	    let _ = CrawlTaskRepo::new(pool).set_failed(task_id).await;
439	}
