441	/// Return a slug that does not already exist in `content_pages`.
442	/// If `base_slug` is taken, appends a numeric suffix.
443	async fn make_unique_slug(pool: &PgPool, base_slug: &str) -> String {
444	    let count: i64 = sqlx::query_scalar(
445	        "SELECT COUNT(*) FROM content_pages WHERE slug LIKE $1 || '%'",
446	    )
447	    .bind(base_slug)
448	    .fetch_one(pool)
449	    .await
450	    .unwrap_or(0);
451	
452	    if count == 0 {
453	        base_slug.to_owned()
454	    } else {
455	        format!("{base_slug}-{count}")
456	    }
457	}
