1	//! RailOps API integration tests.
2	//!
3	//! These tests run against a live backend at TEST_BASE_URL
4	//! (default: https://localhost:8443).
5	//!
6	//! Inside Docker the tester service sets TEST_BASE_URL=https://app:8443.
7	//! Locally, start the stack first with `docker compose up --build`, then:
8	//!   cargo test --test api_integration_test -- --nocapture
9	//!
10	//! Each test is self-contained: it creates a fresh client and obtains its own
11	//! session token.  No shared state between tests.
12	
13	use hmac::{Hmac, Mac};
14	use reqwest::{Client, StatusCode};
15	use serde_json::{json, Value};
16	use sha2::Sha256;
17	
18	const ADMIN_USER: &str = "admin";
19	const ADMIN_PASS: &str = "AdminRailOps2024!";
20	
21	/// Returns the base URL from TEST_BASE_URL env var, falling back to localhost.
22	fn base() -> String {
23	    std::env::var("TEST_BASE_URL")
24	        .unwrap_or_else(|_| "https://localhost:8443".to_owned())
25	}
26	
27	// ── Helpers ───────────────────────────────────────────────────────────────────
28	
29	fn new_client() -> Client {
30	    Client::builder()
31	        .danger_accept_invalid_certs(true) // self-signed cert from rcgen
32	        .build()
33	        .expect("build reqwest client")
34	}
35	
36	/// Compute HMAC-SHA-256 request signature required by the auth middleware.
37	/// Returns (sig_hex, timestamp_string).
38	fn sign(method: &str, path: &str, token: &str) -> (String, String) {
39	    let ts = std::time::SystemTime::now()
40	        .duration_since(std::time::UNIX_EPOCH)
41	        .unwrap()
42	        .as_secs() as i64;
43	    let message = format!("{method}\n{path}\n{ts}");
44	    type HmacSha256 = Hmac<Sha256>;
45	    let mut mac = HmacSha256::new_from_slice(token.as_bytes())
46	        .expect("HMAC accepts any key length");
47	    mac.update(message.as_bytes());
48	    let sig = hex::encode(mac.finalize().into_bytes());
49	    (sig, ts.to_string())
50	}
