69	/// Authenticated GET request with proper HMAC signature headers.
70	async fn authed_get(c: &Client, path: &str, token: &str) -> reqwest::Response {
71	    let (sig, ts) = sign("GET", path, token);
72	    c.get(format!("{}{path}", base()))
73	        .bearer_auth(token)
74	        .header("X-RailOps-Sig", sig)
75	        .header("X-RailOps-Ts", ts)
76	        .send()
77	        .await
78	        .unwrap_or_else(|e| panic!("GET {path} failed: {e}"))
79	}
80	
81	/// Authenticated POST request with JSON body.
82	async fn authed_post(c: &Client, path: &str, token: &str, body: Value) -> reqwest::Response {
83	    let (sig, ts) = sign("POST", path, token);
84	    c.post(format!("{}{path}", base()))
85	        .bearer_auth(token)
86	        .header("X-RailOps-Sig", sig)
87	        .header("X-RailOps-Ts", ts)
88	        .json(&body)
89	        .send()
90	        .await
91	        .unwrap_or_else(|e| panic!("POST {path} failed: {e}"))
92	}
93	
94	/// Authenticated PATCH request with JSON body.
95	async fn authed_patch(c: &Client, path: &str, token: &str, body: Value) -> reqwest::Response {
96	    let (sig, ts) = sign("PATCH", path, token);
97	    c.patch(format!("{}{path}", base()))
98	        .bearer_auth(token)
99	        .header("X-RailOps-Sig", sig)
100	        .header("X-RailOps-Ts", ts)

