207	// ── Helpers ───────────────────────────────────────────────────────────────────
208	
209	async fn get_public<T: for<'de> Deserialize<'de>>(url: &str) -> ApiResult<T> {
210	    let resp = Request::get(url)
211	        .send()
212	        .await
213	        .map_err(|e| ApiError { status: 0, message: e.to_string() })?;
214	
215	    if resp.ok() {
216	        resp.json::<T>().await
217	            .map_err(|e| ApiError { status: 0, message: e.to_string() })
218	    } else {
219	        let status  = resp.status();
220	        let text    = resp.text().await.unwrap_or_default();
221	        let message = serde_json::from_str::<serde_json::Value>(&text)
222	            .ok()
223	            .and_then(|v| v["error"]["message"].as_str().map(str::to_owned))
224	            .unwrap_or(text);
225	        Err(ApiError { status, message })
226	    }
227	}
228	
229	fn urlenc(s: &str) -> String {
230	    js_sys::encode_uri_component(s).as_string().unwrap_or_else(|| s.to_owned())
231	}
