234	
235	fn parse_date_display(iso: &str) -> Option<String> {
236	    let parts: Vec<&str> = iso.split('-').collect();
237	    if parts.len() < 3 { return None; }
238	    let year  = parts[0];
239	    let month = parts[1].parse::<u32>().ok()?;
240	    let day   = parts[2].parse::<u32>().ok()?;
241	    let month_name = match month {
242	        1 => "Jan", 2 => "Feb", 3 => "Mar", 4 => "Apr",
243	        5 => "May", 6 => "Jun", 7 => "Jul", 8 => "Aug",
244	        9 => "Sep", 10 => "Oct", 11 => "Nov", 12 => "Dec",
245	        _ => return None,
246	    };
247	    Some(format!("{month_name} {day}, {year}"))
248	}
249	
250	pub fn month_name(m: i32) -> &'static str {
251	    match m {
252	        1 => "January", 2 => "February", 3 => "March",
253	        4 => "April",   5 => "May",      6 => "June",
254	        7 => "July",    8 => "August",   9 => "September",
255	        10 => "October", 11 => "November", 12 => "December",
256	        _ => "Unknown",
257	    }
258	}
259	
260	pub fn category_label(cat: &str) -> &str {
261	    match cat {
262	        "fares"         => "Fares",
263	        "delays"        => "Delays",
264	        "baggage"       => "Baggage",
265	        "accessibility" => "Accessibility",
266	        _               => "General",
267	    }
268	}
