272	        "fares"         => "bg-green-100 text-green-800",
273	        "delays"        => "bg-red-100 text-red-800",
274	        "baggage"       => "bg-amber-100 text-amber-800",
275	        "accessibility" => "bg-purple-100 text-purple-800",
276	        _               => "bg-gray-100 text-gray-800",
277	    }
278	}
