255	fn index_view(
256	    idx:           &ArchiveIndexResponse,
257	    make_month_cb: &dyn Fn(i32, i32) -> Callback<MouseEvent>,
258	) -> Html {
259	    if idx.entries.is_empty() {
260	        return html! {
261	            <div class="text-center py-20">
262	                <p class="text-slate-500">{"No archived articles yet."}</p>
263	            </div>
264	        };
265	    }
266	
267	    // Group consecutive entries by year (already sorted DESC by the backend).
268	    let mut by_year: Vec<(i32, Vec<&ArchiveEntry>)> = Vec::new();
269	    for entry in &idx.entries {
270	        if let Some(last) = by_year.last_mut() {
271	            if last.0 == entry.year {
272	                last.1.push(entry);
273	                continue;
274	            }
275	        }
276	        by_year.push((entry.year, vec![entry]));
277	    }
278	
279	    html! {
280	        <div>
281	            <h1 class="text-2xl font-bold text-slate-900 mb-8">{"Article Archive"}</h1>
282	            { for by_year.iter().map(|(year, entries)| {
283	                let y = *year;
284	                html! {
285	                    <div key={y} class="mb-10">
286	                        <h2 class="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">
287	                            { y }
288	                        </h2>
289	                        <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
290	                            { for entries.iter().map(|e| {
291	                                html! {
292	                                    <button
293	                                        key={e.month}
294	                                        onclick={make_month_cb(e.year, e.month)}
295	                                        class="bg-white rounded-xl border border-slate-200 p-4 \
296	                                               text-left hover:shadow-md hover:border-indigo-300 \
297	                                               hover:bg-indigo-50/30 active:scale-95 transition group"
298	                                    >
299	                                        <div class="font-semibold text-slate-800
300	                                                    group-hover:text-indigo-700 transition">
301	                                            { month_name(e.month) }
302	                                        </div>
303	                                        <div class="text-xs text-slate-400 mt-1">
304	                                            { format!("{} articles", e.count) }
305	                                        </div>
306	                                    </button>
307	                                }
308	                            }) }
309	                        </div>
310	                    </div>
311	                }
312	            }) }
313	        </div>
314	    }
315	}
