1	//! Kiosk search page.
2	//!
3	//! Features:
4	//! - URL-driven state: all filters are query parameters so results are bookmarkable
5	//! - 300 ms debounced text input
6	//! - Multi-condition filters: full-text query + category + tag
7	//! - FTS results with fuzzy fallback (shown with different heading)
8	//! - Pagination with first/prev/next/last controls
9	//! - Active filter chips with individual remove buttons
10	//! - Tag suggestions sidebar loaded from the API
11	
12	use gloo_timers::callback::Timeout;
13	use wasm_bindgen_futures::spawn_local;
14	use web_sys::HtmlInputElement;
15	use yew::prelude::*;
16	use yew_router::prelude::*;
17	
18	use crate::api::kiosk::{self, category_label, CategoryCount, SearchResponse, TagCount};
19	use crate::app::Route;
20	use crate::pages::kiosk::home::{article_card, footer, nav_bar};
21	
22	// ── URL query params ──────────────────────────────────────────────────────────
23	
24	#[derive(Debug, Clone, PartialEq, serde::Deserialize, serde::Serialize, Default)]
25	pub struct SearchQuery {
26	    #[serde(default, skip_serializing_if = "Option::is_none")]
27	    pub q:              Option<String>,
28	    #[serde(default, skip_serializing_if = "Option::is_none")]
29	    pub category:       Option<String>,
30	    #[serde(default, skip_serializing_if = "Option::is_none")]
31	    pub tag:            Option<String>,
32	    /// ISO-8601 departure lower bound, e.g. `"2026-06-01"`.
33	    #[serde(default, skip_serializing_if = "Option::is_none")]
34	    pub departure_from: Option<String>,
35	    /// ISO-8601 departure upper bound, e.g. `"2026-06-30"`.
36	    #[serde(default, skip_serializing_if = "Option::is_none")]
37	    pub departure_to:   Option<String>,
38	    #[serde(default, skip_serializing_if = "Option::is_none")]
39	    pub page:           Option<i64>,
40	}
41	
42	// ── Component ─────────────────────────────────────────────────────────────────
43	
44	#[function_component(KioskSearchPage)]
45	pub fn kiosk_search() -> Html {
46	    let location  = use_location().unwrap();
47	    let navigator = use_navigator().unwrap();
48	
49	    // Parse URL query params.
50	    let url_q: SearchQuery = location.query::<SearchQuery>().unwrap_or_default();
51	
52	    // Raw input state (what the user is currently typing — debounced).
53	    let raw_input = use_state(|| url_q.q.clone().unwrap_or_default());
54	
55	    // Committed filter state (what was last submitted to the API).
56	    let committed = use_state(|| url_q.clone());
57	
58	    // Results
59	    let results     = use_state(|| Option::<SearchResponse>::None);
60	    let loading     = use_state(|| false);
61	    let error       = use_state(|| Option::<String>::None);
62	
63	    // Sidebar data
64	    let cat_counts = use_state(|| Vec::<CategoryCount>::new());
65	    let top_tags   = use_state(|| Vec::<TagCount>::new());
66	
67	    // ── Load sidebar data once ────────────────────────────────────────────
68	    {
69	        let cat_counts = cat_counts.clone();
70	        let top_tags   = top_tags.clone();
71	        use_effect_with((), move |_| {
72	            spawn_local(async move {
73	                let (cats, tags) = futures::join!(
74	                    kiosk::list_categories(),
75	                    kiosk::list_tags(),
76	                );
77	                if let Ok(c) = cats { cat_counts.set(c); }
78	                if let Ok(t) = tags { top_tags.set(t); }
79	            });
80	            || ()
81	        });
82	    }
83	
84	    // ── Sync raw_input when URL changes externally (e.g. back/forward) ───
85	    {
86	        let raw_input = raw_input.clone();
87	        let committed = committed.clone();
88	        let q_str     = url_q.q.clone().unwrap_or_default();
89	        use_effect_with(url_q.clone(), move |uq| {
90	            raw_input.set(uq.q.clone().unwrap_or_default());
91	            committed.set(uq.clone());
92	            drop(q_str);
93	            || ()
94	        });
95	    }
96	
97	    // ── Run search whenever committed filter changes ───────────────────────
98	    {
99	        let results  = results.clone();
100	        let loading  = loading.clone();
101	        let error    = error.clone();
102	        use_effect_with((*committed).clone(), move |params| {
103	            let params  = params.clone();
104	            let results = results.clone();
105	            let loading = loading.clone();
106	            let error   = error.clone();
107	
108	            loading.set(true);
109	            error.set(None);
110	
111	            spawn_local(async move {
112	                let q              = params.q.as_deref();
113	                let category       = params.category.as_deref();
114	                let tag            = params.tag.as_deref();
115	                let departure_from = params.departure_from.as_deref();
116	                let departure_to   = params.departure_to.as_deref();
117	                let page           = params.page.unwrap_or(1);
118	
119	                match kiosk::search_content(q, category, tag, departure_from, departure_to, page, 12).await {
120	                    Ok(r)  => { results.set(Some(r)); loading.set(false); }
121	                    Err(e) => {
122	                        error.set(Some(e.message));
123	                        results.set(None);
124	                        loading.set(false);
125	                    }
126	                }
127	            });
128	            || ()
129	        });
130	    }
131	
132	    // ── Debounce text input → push URL ────────────────────────────────────
133	    {
134	        let navigator = navigator.clone();
135	        let url_q2    = url_q.clone();
136	        let raw_input = raw_input.clone();
137	        use_effect_with((*raw_input).clone(), move |text| {
138	            let text  = text.clone();
139	            let nav   = navigator.clone();
140	            let mut q = url_q2.clone();
141	            let handle = Timeout::new(300, move || {
142	                q.q    = if text.trim().is_empty() { None } else { Some(text.trim().to_owned()) };
143	                q.page = None;
144	                nav.push_with_query(&Route::KioskSearch, &q).ok();
145	            });
146	            move || drop(handle)
147	        });
148	    }
149	
150	    // ── Departure filter handlers ─────────────────────────────────────────
151	    let on_departure_from = {
152	        let navigator = navigator.clone();
153	        let q = url_q.clone();
154	        Callback::from(move |e: InputEvent| {
155	            let el: HtmlInputElement = e.target_unchecked_into();
156	            let val = el.value();
157	            let mut qq = q.clone();
158	            qq.departure_from = if val.is_empty() { None } else { Some(val) };
159	            qq.page = None;
160	            navigator.push_with_query(&Route::KioskSearch, &qq).ok();
161	        })
162	    };
163	
164	    let on_departure_to = {
165	        let navigator = navigator.clone();
166	        let q = url_q.clone();
167	        Callback::from(move |e: InputEvent| {
168	            let el: HtmlInputElement = e.target_unchecked_into();
169	            let val = el.value();
170	            let mut qq = q.clone();
171	            qq.departure_to = if val.is_empty() { None } else { Some(val) };
172	            qq.page = None;
173	            navigator.push_with_query(&Route::KioskSearch, &qq).ok();
174	        })
175	    };
176	
177	    // ── Event handlers ────────────────────────────────────────────────────
178	    let on_input = {
179	        let raw_input = raw_input.clone();
180	        Callback::from(move |e: InputEvent| {
181	            let el: HtmlInputElement = e.target_unchecked_into();
182	            raw_input.set(el.value());
183	        })
184	    };
185	
186	    let on_clear_query = {
187	        let navigator = navigator.clone();
188	        let q = url_q.clone();
189	        Callback::from(move |_: MouseEvent| {
190	            let mut q = q.clone();
191	            q.q    = None;
192	            q.page = None;
193	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
194	        })
195	    };
196	
197	    let make_category_cb = |cat: Option<String>| {
198	        let navigator = navigator.clone();
199	        let q = url_q.clone();
200	        Callback::from(move |_: MouseEvent| {
201	            let mut q = q.clone();
202	            q.category = cat.clone();
203	            q.page     = None;
204	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
205	        })
206	    };
207	
208	    let make_tag_cb = |tag: Option<String>| {
209	        let navigator = navigator.clone();
210	        let q = url_q.clone();
211	        Callback::from(move |_: MouseEvent| {
212	            let mut q = q.clone();
213	            q.tag  = tag.clone();
214	            q.page = None;
215	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
216	        })
217	    };
218	
219	    let make_page_cb = |p: i64| {
220	        let navigator = navigator.clone();
221	        let q = url_q.clone();
222	        Callback::from(move |_: MouseEvent| {
223	            let mut q = q.clone();
224	            q.page = Some(p);
225	            navigator.push_with_query(&Route::KioskSearch, &q).ok();
226	        })
227	    };
228	
229	    // ── Render ────────────────────────────────────────────────────────────
230	    let active_q           = url_q.q.as_deref().unwrap_or("").to_owned();
231	    let active_category    = url_q.category.clone();
232	    let active_tag         = url_q.tag.clone();
233	    let active_dep_from    = url_q.departure_from.clone().unwrap_or_default();
234	    let active_dep_to      = url_q.departure_to.clone().unwrap_or_default();
235	
236	    html! {
237	        <div class="min-h-screen bg-slate-50">
238	            { nav_bar() }
239	
240	            <div class="max-w-6xl mx-auto px-6 py-8">
241	
242	                // ── Search bar ────────────────────────────────────────────
243	                <div class="flex gap-3 mb-6">
244	                    <div class="relative flex-1">
245	                        <input
246	                            type="search"
247	                            placeholder="Search articles…"
248	                            autocomplete="off"
249	                            value={(*raw_input).clone()}
250	                            oninput={on_input}
251	                            class="w-full rounded-xl border border-slate-300 px-5 py-3 pr-10
252	                                   text-base shadow-sm focus:border-indigo-500 focus:outline-none
253	                                   focus:ring-2 focus:ring-indigo-200"
254	                        />
255	                        if !active_q.is_empty() {
256	                            <button
257	                                onclick={on_clear_query}
258	                                class="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400
259	                                       hover:text-slate-700 text-xl leading-none"
260	                                title="Clear search"
261	                            >{"×"}</button>
262	                        }
263	                    </div>
264	                    <Link<Route> to={Route::Kiosk}
265	                        classes="rounded-xl border border-slate-300 px-4 py-3 text-sm font-medium \
266	                                 text-slate-600 hover:bg-slate-50 transition">
267	                        {"← Home"}
268	                    </Link<Route>>
269	                </div>
270	
271	                // ── Departure window filter ───────────────────────────────
272	                <div class="flex flex-wrap gap-3 mb-4">
273	                    <div class="flex items-center gap-2">
274	                        <label class="text-xs text-slate-500 font-medium whitespace-nowrap">
275	                            {"Departs from"}
276	                        </label>
277	                        <input
278	                            type="date"
279	                            value={active_dep_from.clone()}
280	                            oninput={on_departure_from}
281	                            class="rounded-lg border border-slate-300 px-3 py-2 text-sm \
282	                                   focus:border-indigo-500 focus:outline-none focus:ring-2 \
283	                                   focus:ring-indigo-200"
284	                        />
285	                    </div>
286	                    <div class="flex items-center gap-2">
287	                        <label class="text-xs text-slate-500 font-medium whitespace-nowrap">
288	                            {"to"}
289	                        </label>
290	                        <input
291	                            type="date"
292	                            value={active_dep_to.clone()}
293	                            oninput={on_departure_to}
294	                            class="rounded-lg border border-slate-300 px-3 py-2 text-sm \
295	                                   focus:border-indigo-500 focus:outline-none focus:ring-2 \
296	                                   focus:ring-indigo-200"
297	                        />
298	                    </div>
299	                </div>
300	
301	                // ── Active filter chips ───────────────────────────────────
302	                { active_chips(&active_category, &active_tag, &url_q, navigator.clone()) }
303	
304	                <div class="flex gap-8">
305	                    // ── Sidebar ───────────────────────────────────────────
306	                    <aside class="w-56 shrink-0 hidden lg:block">
307	                        // Category filter
308	                        <div class="bg-white rounded-2xl border border-slate-200 p-4 mb-4">
309	                            <h3 class="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">
310	                                {"Category"}
311	                            </h3>
312	                            <ul class="space-y-1">
313	                                <li>
314	                                    <button
315	                                        onclick={make_category_cb(None)}
316	                                        class={sidebar_btn_class(active_category.is_none())}
317	                                    >
318	                                        {"All topics"}
319	                                    </button>
320	                                </li>
321	                                { for (*cat_counts).iter().map(|cc| {
322	                                    let active = active_category.as_deref() == Some(&cc.category);
323	                                    let cat    = cc.category.clone();
324	                                    let cnt    = cc.count;
325	                                    html! {
326	                                        <li key={cat.clone()}>
327	                                            <button
328	                                                onclick={make_category_cb(Some(cat))}
329	                                                class={sidebar_btn_class(active)}
330	                                            >
331	                                                <span>{ category_label(&cc.category) }</span>
332	                                                <span class="ml-auto text-xs text-slate-400">{ cnt }</span>
333	                                            </button>
334	                                        </li>
335	                                    }
336	                                }) }
337	                            </ul>
338	                        </div>
339	
340	                        // Top tags
341	                        if !(*top_tags).is_empty() {
342	                            <div class="bg-white rounded-2xl border border-slate-200 p-4">
343	                                <h3 class="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">
344	                                    {"Popular Tags"}
345	                                </h3>
346	                                <div class="flex flex-wrap gap-2">
347	                                    { for (*top_tags).iter().take(20).map(|tc| {
348	                                        let active = active_tag.as_deref() == Some(&tc.tag);
349	                                        let tag    = tc.tag.clone();
350	                                        html! {
351	                                            <button
352	                                                key={tag.clone()}
353	                                                onclick={make_tag_cb(if active { None } else { Some(tag) })}
354	                                                class={if active {
355	                                                    "text-xs rounded-full px-2.5 py-0.5 bg-indigo-600 \
356	                                                     text-white font-medium"
357	                                                } else {
358	                                                    "text-xs rounded-full px-2.5 py-0.5 bg-slate-100 \
359	                                                     text-slate-700 hover:bg-indigo-100 hover:text-indigo-700"
360	                                                }}
361	                                            >
362	                                                { &tc.tag }
363	                                            </button>
364	                                        }
365	                                    }) }
366	                                </div>
367	                            </div>
368	                        }
369	                    </aside>
370	
371	                    // ── Results area ──────────────────────────────────────
372	                    <div class="flex-1 min-w-0">
373	                        { results_panel(&results, &loading, &error, &active_q, &make_page_cb) }
374	                    </div>
375	                </div>
376	            </div>
377	
378	            { footer() }
379	        </div>
380	    }
381	}
