383	// ── Helper components / functions ─────────────────────────────────────────────
384	
385	fn active_chips(
386	    category: &Option<String>,
387	    tag:      &Option<String>,
388	    url_q:    &SearchQuery,
389	    nav:      Navigator,
390	) -> Html {
391	    if category.is_none() && tag.is_none() {
392	        return html! {};
393	    }
394	    html! {
395	        <div class="flex flex-wrap gap-2 mb-4">
396	            if let Some(cat) = category {
397	                { {
398	                    let mut q = url_q.clone();
399	                    let nav2  = nav.clone();
400	                    let c2    = cat.clone();
401	                    let onclick = Callback::from(move |_: MouseEvent| {
402	                        let mut qq = q.clone();
403	                        qq.category = None;
404	                        qq.page     = None;
405	                        nav2.push_with_query(&Route::KioskSearch, &qq).ok();
406	                    });
407	                    html! {
