531	fn pagination(
532	    current:      i64,
533	    total:        i64,
534	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
535	) -> Html {
536	    html! {
537	        <div class="flex items-center justify-center gap-2">
538	            <button
539	                onclick={make_page_cb(1)}
540	                disabled={current == 1}
541	                class={page_btn_class(false, current == 1)}
542	            >{"«"}</button>
543	            <button
544	                onclick={make_page_cb((current - 1).max(1))}
545	                disabled={current == 1}
546	                class={page_btn_class(false, current == 1)}
547	            >{"‹"}</button>
548	
549	            { for visible_pages(current, total).into_iter().map(|p| {
550	                let active = p == current;
551	                html! {
552	                    <button
553	                        key={p}
554	                        onclick={make_page_cb(p)}
555	                        class={page_btn_class(active, false)}
556	                    >
557	                        { p }
558	                    </button>
559	                }
560	            }) }
561	
562	            <button
563	                onclick={make_page_cb((current + 1).min(total))}
564	                disabled={current == total}
565	                class={page_btn_class(false, current == total)}
566	            >{"›"}</button>
567	            <button
568	                onclick={make_page_cb(total)}
569	                disabled={current == total}
570	                class={page_btn_class(false, current == total)}
571	            >{"»"}</button>
572	        </div>
573	    }
574	}
575	
576	fn visible_pages(current: i64, total: i64) -> Vec<i64> {
577	    let window = 2i64;
578	    let start  = (current - window).max(1);
579	    let end    = (current + window).min(total);
580	    (start..=end).collect()
581	}
582	
583	fn page_btn_class(active: bool, disabled: bool) -> &'static str {
584	    if disabled      { "w-9 h-9 rounded-lg text-sm text-slate-300 cursor-not-allowed" }
585	    else if active   { "w-9 h-9 rounded-lg text-sm bg-indigo-700 text-white font-bold" }
586	    else             { "w-9 h-9 rounded-lg text-sm border border-slate-200 \
587	                        text-slate-700 hover:bg-slate-50" }
588	}
