592	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
593	         bg-indigo-50 text-indigo-700 font-semibold text-sm"
594	    } else {
595	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
596	         text-slate-700 text-sm hover:bg-slate-50 transition"
597	    }
598	}
