46	    // rustls 0.23 requires an explicit process-level CryptoProvider.
47	    rustls::crypto::ring::default_provider()
48	        .install_default()
49	        .expect("Failed to install rustls ring crypto provider");
50	
51	    init_tracing();
52	
53	    let cfg = AppConfig::from_env().context("Failed to load configuration")?;
54	    info!(host = %cfg.server.host, port = cfg.server.port, "Starting RailOps backend");
55	
56	    // ── Security posture check ─────────────────────────────────────────────────
57	    const DEFAULT_SECRET:   &str = "change_this_to_a_random_64_char_string_before_going_live_!!1";
58	    const DEFAULT_SEED_PW:  &str = "AdminRailOps2024!";
59	    if cfg.security.session_secret == DEFAULT_SECRET {
60	        tracing::warn!(
61	            "SESSION_SECRET is set to the well-known default value. \
62	             Set a unique random secret before deploying to production."
63	        );
64	    }
65	    if cfg.security.admin_seed_password == DEFAULT_SEED_PW {
66	        tracing::warn!(
67	            "ADMIN_SEED_PASSWORD is set to the well-known default value. \
68	             Change the admin password immediately after first login in production."
69	        );
70	    }
71	
72	    ensure_tls_certs(&cfg.tls).context("TLS setup failed")?;
73	    let tls_config = build_tls_config(&cfg.tls).context("Failed to build TLS config")?;
74	
75	    let pool = PgPoolOptions::new()
76	        .max_connections(cfg.database.max_connections)
77	        .connect(&cfg.database.url())
78	        .await
79	        .context("Failed to connect to PostgreSQL")?;
80	    info!("Connected to PostgreSQL");
81	
82	    sqlx::migrate!("../migrations")
83	        .run(&pool)
84	        .await
85	        .context("Database migration failed")?;
86	    info!("Migrations applied");
87	
88	    seed_pending_passwords(&pool, &cfg.security.admin_seed_password).await?;
89	
90	    // ── Crawl engine ───────────────────────────────────────────────────────────
91	    let (trigger_handle, trigger_rx) = TriggerHandle::new();
92	    CrawlEngine::new(pool.clone(), shared::rules::CRAWL_MAX_WORKERS).spawn(trigger_rx);
93	    info!("CrawlEngine started in background");
94	
95	    // ── Background jobs: hold-expiry + PII-purge ──────────────────────────────
96	    {
97	        let pool_bg = pool.clone();
98	        tokio::spawn(async move {
99	            use crate::domain::orders::repo::{OrderRepo, OrderEventRepo, PassengerRepo};
100	            use crate::domain::orders::models::NewOrderEvent;
101	            use crate::db::audit::write_audit;
102	            use serde_json::json;
103	
104	            let mut hold_tick = tokio::time::interval(Duration::from_secs(30));
105	            hold_tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
106	            let mut purge_tick = tokio::time::interval(Duration::from_secs(300));
107	            purge_tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
108	
109	            loop {
110	                tokio::select! {
111	                    _ = hold_tick.tick() => {
112	                        // Expire held orders past their hold_expires_at
113	                        // First get the IDs that will be expired so we can log events
114	                        let expired_ids: Vec<(uuid::Uuid,)> = sqlx::query_as(
115	                            "SELECT id FROM orders WHERE status = 'held' AND hold_expires_at < NOW()"
116	                        )
117	                        .fetch_all(&pool_bg)
118	                        .await
119	                        .unwrap_or_default();
120	
121	                        if !expired_ids.is_empty() {
122	                            match OrderRepo::new(&pool_bg).expire_holds().await {
123	                                Ok(n) if n > 0 => {
124	                                    for (oid,) in &expired_ids {
125	                                        let _ = OrderEventRepo::new(&pool_bg).insert(&NewOrderEvent {
126	                                            order_id: *oid,
127	                                            event_type: "hold_expired".into(),
128	                                            performed_by: None,
129	                                            reason: Some("Automatic hold expiry after TTL".into()),
130	                                            data: None,
131	                                        }).await;
132	                                        write_audit(
133	                                            &pool_bg, "hold_expired", "orders", Some(*oid),
134	                                            None, "auto_expire", None,
135	                                            Some(json!({"reason": "hold TTL exceeded"})), None,
136	                                        ).await;
137	                                    }
138	                                    info!(count = n, "Auto-expired held orders");
139	                                }
140	                                Ok(_) => {}
141	                                Err(e) => warn!(error = %e, "Hold expiry check failed"),
142	                            }
143	                        }
144	                    }
145	                    _ = purge_tick.tick() => {
146	                        // PII purge: find passengers with purge requested, whose most
147	                        // recent order departure is > 30 days ago
148	                        let eligible: Vec<(uuid::Uuid,)> = sqlx::query_as(
149	                            "SELECT p.id FROM passengers p
