167	                                        &pool_bg, "pii_purged", "passengers", Some(*pid),
168	                                        None, "auto_purge", None,
169	                                        Some(json!({"reason": "30 days post-trip + purge request"})),
170	                                        None,
171	                                    ).await;
172	                                    info!(passenger_id = %pid, "PII purge executed");
173	                                }
174	                                Err(e) => warn!(passenger_id = %pid, error = %e, "PII purge failed"),
175	                            }
176	                        }
177	                    }
178	                }
179	            }
180	        });
181	        info!("Background jobs started (hold-expiry + PII-purge)");
182	    }
183	
