412	/// Replace every `SEED_PENDING` hash in the users table with a real Argon2id hash.
413	async fn seed_pending_passwords(pool: &sqlx::PgPool, seed_pw: &str) -> Result<()> {
414	    let pending: Vec<(uuid::Uuid, String)> = sqlx::query_as(
415	        "SELECT id, username FROM users WHERE password_hash = 'SEED_PENDING'",
416	    )
417	    .fetch_all(pool)
418	    .await
419	    .context("Failed to query pending password seeds")?;
420	
421	    for (id, username) in &pending {
422	        if let Some(err) = crypto::validate_password(seed_pw) {
423	            anyhow::bail!("Seed password rejected: {err}");
424	        }
425	        let hash = crypto::hash_password(seed_pw)
426	            .context("Failed to hash seed password")?;
427	        sqlx::query("UPDATE users SET password_hash = $1 WHERE id = $2")
428	            .bind(&hash)
429	            .bind(id)
430	            .execute(pool)
431	            .await
432	            .context("Failed to update seeded password")?;
433	        info!(username = %username, "Password seeded");
434	    }
435	    Ok(())
436	}
