438	// ── TLS ───────────────────────────────────────────────────────────────────────
439	
440	fn ensure_tls_certs(tls: &config::TlsConfig) -> Result<()> {
441	    let cert_path = std::path::Path::new(&tls.cert_path);
442	    let key_path  = std::path::Path::new(&tls.key_path);
443	    if cert_path.exists() && key_path.exists() { return Ok(()); }
444	
445	    warn!("Generating self-signed TLS certificate");
446	    let cert = rcgen::generate_simple_self_signed(
447	        vec!["localhost".to_owned(), "railops.local".to_owned()],
448	    )
449	    .context("rcgen failed")?;
450	
451	    if let Some(p) = cert_path.parent() { std::fs::create_dir_all(p)?; }
452	    std::fs::write(cert_path, cert.serialize_pem().context("cert PEM")?)?;
453	    std::fs::write(key_path,  cert.serialize_private_key_pem())?;
454	    info!(cert = %tls.cert_path, "TLS certificate written");
455	    Ok(())
456	}
457	
458	fn build_tls_config(tls: &config::TlsConfig) -> Result<rustls::ServerConfig> {
459	    use rustls::pki_types::{CertificateDer, PrivateKeyDer};
460	    use rustls_pemfile::{certs, private_key};
461	    use std::{fs::File, io::BufReader};
462	
463	    let cert_chain: Vec<CertificateDer<'static>> =
464	        certs(&mut BufReader::new(File::open(&tls.cert_path)?))
465	            .collect::<std::result::Result<_, _>>()
466	            .context("Failed to parse cert chain")?;
467	    let key: PrivateKeyDer<'static> =
468	        private_key(&mut BufReader::new(File::open(&tls.key_path)?))
469	            .context("Failed to read private key")?
470	            .ok_or_else(|| anyhow::anyhow!("No private key in {}", tls.key_path))?;
471	
472	    rustls::ServerConfig::builder()
473	        .with_no_client_auth()
474	        .with_single_cert(cert_chain, key)
475	        .context("Invalid TLS cert/key pair")
476	}
