1	//! Background crawl engine.
2	//!
3	//! [`CrawlEngine`] runs as a long-lived tokio task that wakes every 60 seconds
4	//! (or immediately when triggered via the [`TriggerHandle`]), queries the DB
5	//! for due tasks, and spawns a bounded worker per task.
6	//!
7	//! ## Worker lifecycle
8	//!
9	//! ```text
10	//! list_due() → [task₁, task₂, …]
11	//!   for each task (bounded by Semaphore):
12	//!     set_running(task)
13	//!     run_id = CrawlRunRepo::start()
14	//!     loop {
15	//!       read_page(cursor) → (items, next_cursor)
16	//!       for each item:
17	//!         transform → fingerprint-dedup → score → ingest / quarantine
18	//!       increment_counters
19	//!       cursor = next_cursor or break if None
20	//!     }
21	//!     CrawlRunRepo::finish()
22	//!     CrawlTaskRepo::complete(cursor, next_crawl_at)
23	//! ```
24	
25	use std::sync::Arc;
26	
27	use chrono::Utc;
28	use serde_json::json;
29	use sqlx::PgPool;
30	use tokio::sync::Semaphore;
31	use tokio::time::{interval, Duration, MissedTickBehavior};
32	use tracing::{error, info, warn};
33	
34	use crate::domain::content::models::CreateContent;
35	use crate::domain::content::repo::ContentRepo;
36	use crate::domain::crawl::models::{CrawlTask, NewQualityLog};
37	use crate::domain::crawl::repo::{CrawlRunRepo, CrawlSourceRepo, CrawlTaskRepo, QualityRepo};
38	
39	use super::pipeline;
40	use super::quality::QualityScorer;
41	use super::reader::reader_for;
42	
43	// ── Trigger handle ────────────────────────────────────────────────────────────
44	
45	/// Allows HTTP handlers to wake the engine without waiting for the next tick.
46	pub struct TriggerHandle {
47	    tx: tokio::sync::watch::Sender<()>,
48	}
49	
50	impl TriggerHandle {
51	    /// Create a handle and its paired receiver (passed to `CrawlEngine::spawn`).
52	    pub fn new() -> (Self, tokio::sync::watch::Receiver<()>) {
53	        let (tx, rx) = tokio::sync::watch::channel(());
54	        (Self { tx }, rx)
55	    }
56	
57	    /// Send a wake signal to the engine.
58	    pub fn notify(&self) {
59	        let _ = self.tx.send(());
60	    }
61	}
62	
63	// ── Engine ────────────────────────────────────────────────────────────────────
64	
65	pub struct CrawlEngine {
66	    pool:      PgPool,
67	    semaphore: Arc<Semaphore>,
68	}
69	
70	impl CrawlEngine {
71	    /// Create a new engine. `max_workers` bounds concurrent crawl workers.
72	    pub fn new(pool: PgPool, max_workers: usize) -> Self {
73	        Self {
74	            pool,
75	            semaphore: Arc::new(Semaphore::new(max_workers.max(1))),
76	        }
77	    }
78	
79	    /// Spawn the engine as a background task.
80	    ///
81	    /// The engine wakes either on its 60-second tick or when the
82	    /// `trigger_rx` channel receives a value.
83	    pub fn spawn(self, mut trigger_rx: tokio::sync::watch::Receiver<()>) {
84	        tokio::spawn(async move {
85	            let mut tick = interval(Duration::from_secs(60));
86	            tick.set_missed_tick_behavior(MissedTickBehavior::Skip);
87	
88	            info!(
89	                max_workers = self.semaphore.available_permits(),
90	                "CrawlEngine started"
91	            );
92	
93	            loop {
94	                tokio::select! {
95	                    _ = tick.tick()          => {}
96	                    _ = trigger_rx.changed() => {
97	                        info!("CrawlEngine woken by trigger");
98	                    }
99	                }
100	                self.dispatch_due_tasks().await;

1	//! `AuthUser` — Actix `FromRequest` extractor that:
2	//!   1. Reads `Authorization: Bearer <token>`
3	//!   2. Verifies the HMAC-SHA-256 request signature (`X-RailOps-Sig` / `X-RailOps-Ts`)
4	//!   3. Looks up the session by `sha256(token)`, enforcing idle + absolute expiry
5	//!   4. Enforces IP binding: request IP must match the IP stored at login time
6	//!   5. Enforces per-session rate limiting (default 60 req/min)
7	//!   6. Bumps `last_active_at` to reset the idle window
8	//!
9	//! IP strategy: uses the direct TCP peer address (`req.peer_addr()`) — not any
10	//! forwarded/proxy header — so it cannot be spoofed by a client.  Sessions that
11	//! pre-date the IP binding feature (stored ip_address IS NULL) are allowed through
12	//! to preserve backward compatibility with existing sessions.
13	//!
14	//! Signing protocol:
15	//!   message  = "METHOD\nPATH_WITH_QUERY\nUNIX_TIMESTAMP_SECS"
16	//!   key      = raw Bearer token
17	//!   sig      = HMAC-SHA-256(key, message) — hex-encoded, in X-RailOps-Sig header
18	//!   Timestamp must be within ±120 s of server time.
19	//!
20	//!   PATH_WITH_QUERY = path + "?" + query_string  (if query_string is non-empty)
21	//!                   = path                        (if query_string is empty)
22	//!
23	//! This ensures query parameters are covered by the signature, preventing
24	//! replay attacks that tamper with query string values.
25	
26	use actix_web::{dev::Payload, web, FromRequest, HttpRequest};
27	use chrono::Utc;
28	use dashmap::DashMap;
29	use futures::future::LocalBoxFuture;
30	use sqlx::PgPool;
31	use tracing::warn;
32	use uuid::Uuid;
33	
34	use shared::UserRole;
35	
36	use crate::error::{AppError, AppResult};
37	
38	use super::session;
39	
40	// ── Rate limiter ──────────────────────────────────────────────────────────────
41	
42	/// In-memory, lock-free rate limiter keyed by session `token_hash`.
43	/// Each entry is `(request_count, window_start_unix_secs)`.
44	pub struct RateLimiter {
45	    store:   DashMap<String, (u32, i64)>,
46	    max_rpm: u32,
47	}
48	
49	impl RateLimiter {
50	    pub fn new(max_rpm: u32) -> Self {
51	        Self { store: DashMap::new(), max_rpm }
52	    }
53	
54	    /// Increment the counter for `key`.  Returns `Err(RateLimited)` if exceeded.
55	    pub fn check_and_increment(&self, key: &str) -> AppResult<()> {
56	        let now = Utc::now().timestamp();
57	        let window = 60_i64; // 1-minute fixed window
58	
59	        let mut entry = self.store.entry(key.to_owned()).or_insert((0, now));
60	        let (count, window_start) = entry.value_mut();
61	
62	        if now - *window_start >= window {
63	            // New window
64	            *window_start = now;
65	            *count = 1;
66	        } else {
67	            *count += 1;
68	            if *count > self.max_rpm {
69	                let retry_after = (window - (now - *window_start)).max(1) as u64;
70	                return Err(AppError::RateLimited { retry_after });
71	            }
72	        }
73	        Ok(())
74	    }
75	
76	    /// Evict entries for expired windows (call periodically to bound memory use).
77	    pub fn evict_expired(&self) {
78	        let now = Utc::now().timestamp();
79	        self.store.retain(|_, (_, window_start)| now - *window_start < 120);
80	    }
81	}
