83	// ── AuthUser ──────────────────────────────────────────────────────────────────
84	
85	/// The authenticated identity injected into every protected handler.
86	#[derive(Debug, Clone)]
87	pub struct AuthUser {
88	    pub id:         Uuid,
89	    pub username:   String,
90	    pub role:       UserRole,
91	    pub full_name:  Option<String>,
92	    /// SHA-256 of the raw token — used for logout / rate-limit key.
93	    pub token_hash: String,
94	}
95	
96	impl FromRequest for AuthUser {
97	    type Error = AppError;
98	    type Future = LocalBoxFuture<'static, AppResult<AuthUser>>;
99	
100	    fn from_request(req: &HttpRequest, _: &mut Payload) -> Self::Future {
101	        // Extract everything we need from the request before entering the async block.
102	        let pool    = req.app_data::<web::Data<PgPool>>()
103	            .cloned()
104	            .expect("PgPool not registered in app_data");
105	        let limiter = req.app_data::<web::Data<RateLimiter>>()
106	            .cloned()
107	            .expect("RateLimiter not registered in app_data");
108	
109	        let method     = req.method().as_str().to_uppercase();
110	        let path       = req.path().to_owned();
111	        let qs         = req.query_string().to_owned();
112	        // Extract IP from direct TCP peer; strip port to get bare IP string.
113	        let client_ip: Option<String> = req.peer_addr()
114	            .map(|addr| addr.ip().to_string());
115	
116	        let token = extract_bearer(req);
117	        let ts    = extract_header_i64(req, "X-RailOps-Ts");
118	        let sig   = extract_header_str(req, "X-RailOps-Sig");
119	
120	        Box::pin(async move {
121	            // ── 1. Token present ─────────────────────────────────────────
122	            let raw_token = token.ok_or_else(|| {
123	                AppError::Unauthorized("Missing Authorization: Bearer token".into())
124	            })?;
125	
126	            // ── 2. Signature + timestamp ─────────────────────────────────
127	            let ts = ts.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Ts".into()))?;
128	            let sig = sig.ok_or_else(|| AppError::Unauthorized("Missing X-RailOps-Sig".into()))?;
129	
130	            let now = Utc::now().timestamp();
131	            if (now - ts).abs() > 120 {
132	                return Err(AppError::Unauthorized("Request timestamp out of window".into()));
133	            }
134	
135	            // Include query string in the signed message to prevent query-param tampering.
136	            let path_with_query = if qs.is_empty() {
137	                path.clone()
138	            } else {
139	                format!("{path}?{qs}")
140	            };
141	            let message = format!("{method}\n{path_with_query}\n{ts}");
142	            if !crate::crypto::hmac_verify(&raw_token, &message, &sig) {
143	                warn!(path = %path_with_query, "Invalid request signature");
144	                return Err(AppError::Unauthorized("Invalid request signature".into()));
145	            }
146	
147	            // ── 3. Session lookup ────────────────────────────────────────
148	            let token_hash = crate::crypto::sha256_hex(&raw_token);
149	
150	            let record = session::find_active_session(&pool, &token_hash)
151	                .await?
152	                .ok_or_else(|| AppError::Unauthorized("Session not found or expired".into()))?;
153	
154	            // ── 4. Session IP binding ────────────────────────────────────
155	            // If the session has a stored IP (set at login), the request IP
156	            // must match.  NULL stored IP means the session pre-dates this
157	            // feature — skip enforcement.
158	            //
159	            // Fail-closed: if the session has a bound IP but we cannot
160	            // resolve the request peer address, reject the request rather
161	            // than silently bypassing the security control.
162	            if let Some(stored_ip) = &record.ip_address {
163	                match &client_ip {
164	                    None => {
165	                        warn!(
166	                            stored_ip = %stored_ip,
167	                            "Session has bound IP but request peer address is unavailable \
168	                             — rejecting (fail-closed)"
169	                        );
170	                        return Err(AppError::Unauthorized(
171	                            "Cannot verify session IP binding".into()
172	                        ));
173	                    }
174	                    Some(req_ip) if stored_ip != req_ip => {
175	                        warn!(
176	                            stored_ip = %stored_ip,
177	                            client_ip = %req_ip,
178	                            "Session IP mismatch — rejecting request"
179	                        );
180	                        return Err(AppError::Unauthorized(
181	                            "Session IP mismatch".into()
182	                        ));
183	                    }
184	                    _ => {} // IPs match — continue
185	                }
186	            }
187	
188	            // ── 5. Rate limiting ─────────────────────────────────────────
189	            limiter.check_and_increment(&token_hash)?;
190	
191	            // ── 5. Touch session (reset idle expiry) ─────────────────────
192	            session::touch_session(&pool, &token_hash).await?;
193	
194	            // Compute role before moving username out of record (E0382 fix:
195	            // user_role() borrows self, which must happen before partial move).
196	            let role = record.user_role();
197	            Ok(AuthUser {
198	                id:         record.user_id,
199	                username:   record.username,
200	                role,
201	                full_name:  record.full_name,
202	                token_hash,
203	            })
204	        })
205	    }
206	}
207	
208	// ── Header extraction helpers ─────────────────────────────────────────────────
209	
210	fn extract_bearer(req: &HttpRequest) -> Option<String> {
211	    req.headers()
212	        .get("Authorization")
213	        .and_then(|v| v.to_str().ok())
214	        .and_then(|v| v.strip_prefix("Bearer "))
215	        .map(|s| s.to_owned())
216	}
217	
218	fn extract_header_i64(req: &HttpRequest, name: &str) -> Option<i64> {
219	    req.headers()
220	        .get(name)
221	        .and_then(|v| v.to_str().ok())
222	        .and_then(|v| v.parse().ok())
223	}
224	
225	fn extract_header_str(req: &HttpRequest, name: &str) -> Option<String> {
226	    req.headers()
227	        .get(name)
228	        .and_then(|v| v.to_str().ok())
229	        .map(|s| s.to_owned())
230	}
