1	//! Role-based access control.
2	//!
3	//! Each handler that needs authorisation declares its required `Permission`
4	//! as a typed Actix extractor.  Extractors build on top of `AuthUser` so the
5	//! full auth + rate-limit pipeline runs first.
6	
7	use actix_web::{dev::Payload, FromRequest, HttpRequest};
8	use futures::future::{ready, Ready};
9	
10	use shared::UserRole;
11	
12	use crate::error::AppError;
13	
14	use super::middleware::AuthUser;
15	
16	// ── Permission catalogue ──────────────────────────────────────────────────────
17	
18	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
19	pub enum Permission {
20	    // Content / kiosk
21	    ViewContent,
22	    ManageContent,
23	
24	    // Scheduling & inventory
25	    ViewSchedules,
26	    ManageSchedules,
27	
28	    // Orders
29	    ViewOrders,
30	    ManageOrders,    // rebook, cancel
31	    OverrideFees,    // fee waiver; requires reason note
32	    ProcessRefunds,
33	
34	    // Staffing
35	    ViewContractors,
36	    ManageContractors,
37	    ManageShifts,
38	
39	    // Credentials
40	    ViewCredentials,
41	    ApproveCredentials,
42	
43	    // Data ingestion
44	    ManageCrawl,
45	
46	    // Administration
47	    ManageUsers,
48	    ConfigureRules,
49	    ViewAuditLog,
50	}
51	
52	/// Local extension trait — allows calling `.has(perm)` on `UserRole` from
53	/// inside this module (including macro expansions) without defining an inherent
54	/// impl on a type that belongs to the `shared` crate (which would be E0116).
55	trait RoleExt {
56	    fn has(&self, perm: Permission) -> bool;
57	}
58	
59	impl RoleExt for UserRole {
60	    fn has(&self, perm: Permission) -> bool {
61	        use Permission::*;
62	        match self {
63	            UserRole::Admin => true, // all permissions
64	
65	            UserRole::OpsAgent => matches!(
66	                perm,
67	                ViewContent
68	                | ManageContent
69	                | ViewSchedules
70	                | ManageSchedules
71	                | ViewOrders
72	                | ManageOrders
73	                | OverrideFees
74	                | ProcessRefunds
75	                | ViewContractors
76	                | ViewCredentials
77	                | ManageCrawl
78	                | ViewAuditLog
79	            ),
80	
81	            // Customer-Service agents can manage/cancel orders, process refunds, and
82	            // apply fee overrides — but must supply a mandatory reason note.
83	            UserRole::CsAgent => matches!(
84	                perm,
85	                ViewContent | ViewSchedules | ViewOrders | ManageOrders | ProcessRefunds
86	                | OverrideFees
87	            ),
88	
89	            UserRole::Dispatcher => matches!(
90	                perm,
91	                ViewContent
92	                | ViewSchedules
93	                | ViewContractors
94	                | ManageContractors
95	                | ManageShifts
96	                | ViewCredentials
97	                | ApproveCredentials
98	                | ViewAuditLog
99	            ),
100	
101	            UserRole::Kiosk => matches!(perm, ViewContent),
102	        }
103	    }
104	}
105	
106	// ── Typed permission extractors ───────────────────────────────────────────────
107	// Each guard is a newtype around AuthUser.  Handlers declare the guard they need
108	// as a parameter; Actix calls from_request which enforces the role check.
109	
110	macro_rules! permission_guard {
111	    ($guard:ident, $perm:expr) => {
112	        /// Actix extractor that requires `AuthUser` + specific permission.
113	        pub struct $guard(pub AuthUser);
114	
115	        impl std::ops::Deref for $guard {
116	            type Target = AuthUser;
117	            fn deref(&self) -> &AuthUser { &self.0 }
118	        }
119	
120	        impl FromRequest for $guard {
121	            type Error = AppError;
122	            type Future = futures::future::LocalBoxFuture<'static, Result<Self, AppError>>;
123	
124	            fn from_request(req: &HttpRequest, payload: &mut Payload) -> Self::Future {
125	                let fut = AuthUser::from_request(req, payload);
126	                Box::pin(async move {
127	                    let user = fut.await?;
128	                    if !user.role.has($perm) {
129	                        return Err(AppError::Forbidden(format!(
130	                            "Role `{}` lacks permission `{:?}`",
131	                            user.role.as_str(), $perm
132	                        )));
133	                    }
134	                    Ok($guard(user))
135	                })
136	            }
137	        }
138	    };
139	}
140	
141	permission_guard!(RequireViewContent,       Permission::ViewContent);
142	permission_guard!(RequireManageContent,     Permission::ManageContent);
143	permission_guard!(RequireViewSchedules,     Permission::ViewSchedules);
144	permission_guard!(RequireManageSchedules,   Permission::ManageSchedules);
145	permission_guard!(RequireViewOrders,        Permission::ViewOrders);
146	permission_guard!(RequireManageOrders,      Permission::ManageOrders);
147	permission_guard!(RequireOverrideFees,      Permission::OverrideFees);
148	permission_guard!(RequireProcessRefunds,    Permission::ProcessRefunds);
149	permission_guard!(RequireViewContractors,   Permission::ViewContractors);
150	permission_guard!(RequireManageContractors, Permission::ManageContractors);
151	permission_guard!(RequireManageShifts,      Permission::ManageShifts);
152	permission_guard!(RequireViewCredentials,   Permission::ViewCredentials);
153	permission_guard!(RequireApproveCredentials,Permission::ApproveCredentials);
154	permission_guard!(RequireManageCrawl,       Permission::ManageCrawl);
155	permission_guard!(RequireManageUsers,       Permission::ManageUsers);
156	permission_guard!(RequireConfigureRules,    Permission::ConfigureRules);
157	permission_guard!(RequireViewAuditLog,      Permission::ViewAuditLog);
158	
159	// ── Convenience: any authenticated non-kiosk staff member ────────────────────
160	
161	pub struct StaffUser(pub AuthUser);
162	
163	impl std::ops::Deref for StaffUser {
164	    type Target = AuthUser;
165	    fn deref(&self) -> &AuthUser { &self.0 }
166	}
167	
168	impl FromRequest for StaffUser {
169	    type Error = AppError;
170	    type Future = futures::future::LocalBoxFuture<'static, Result<Self, AppError>>;
171	
172	    fn from_request(req: &HttpRequest, payload: &mut Payload) -> Self::Future {
173	        let fut = AuthUser::from_request(req, payload);
174	        Box::pin(async move {
175	            let user = fut.await?;
176	            if user.role == UserRole::Kiosk {
177	                return Err(AppError::Forbidden("Kiosk access not permitted here".into()));
178	            }
179	            Ok(StaffUser(user))
180	        })
181	    }
182	}
