121	pub async fn list_contractors(
122	    pool:  web::Data<sqlx::PgPool>,
123	    query: web::Query<ContractorListQuery>,
124	    _auth: RequireViewContractors,
125	) -> AppResult<HttpResponse> {
126	    let q        = query.into_inner();
127	    let page     = q.page.unwrap_or(1).max(1);
128	    let per_page = q.per_page.unwrap_or(20).clamp(1, 100);
129	    let result   = ContractorRepo::new(&pool)
130	        .list(q.region.as_deref(), q.is_active, page, per_page)
131	        .await?;
132	    Ok(HttpResponse::Ok().json(result))
133	}
