135	pub async fn get_contractor(
136	    pool:  web::Data<sqlx::PgPool>,
137	    path:  web::Path<Uuid>,
138	    _auth: RequireViewContractors,
139	) -> AppResult<HttpResponse> {
140	    let id   = path.into_inner();
141	    let repo = ContractorRepo::new(&pool);
142	    let contractor = repo
