463	pub async fn list_subscriptions(
464	    pool: web::Data<sqlx::PgPool>,
465	    auth: RequireViewContractors,
466	) -> AppResult<HttpResponse> {
467	    // Dispatcher subscriptions are keyed to the user UUID.
468	    let dispatcher_subs = SubscriptionRepo::new(&pool)
469	        .list_for_subscriber("dispatcher", auth.id)
470	        .await?;
471	
472	    // Contractor subscriptions are keyed to the contractor UUID (not the user UUID).
473	    // Look up the contractor record linked to this user account.
474	    let contractor_subs =
475	        match ContractorRepo::new(&pool).find_id_by_user_id(auth.id).await? {
476	            Some(contractor_id) => {
477	                SubscriptionRepo::new(&pool)
478	                    .list_for_subscriber("contractor", contractor_id)
479	                    .await?
480	            }
481	            None => vec![],
482	        };
483	
484	    let mut all = dispatcher_subs;
485	    all.extend(contractor_subs);
486	    Ok(HttpResponse::Ok().json(all))
487	}
