489	/// Resolve the subscriber UUID for the given `subscriber_type`.
490	///
491	/// - `"dispatcher"` → user's own UUID
492	/// - `"contractor"` → the contractor record UUID linked to this user account
493	async fn resolve_subscriber_id(
494	    pool:            &sqlx::PgPool,
495	    user_id:         uuid::Uuid,
496	    subscriber_type: &str,
497	) -> AppResult<uuid::Uuid> {
498	    if subscriber_type == "contractor" {
499	        ContractorRepo::new(pool)
500	            .find_id_by_user_id(user_id)
501	            .await?
502	            .ok_or_else(|| AppError::Validation(
503	                "No contractor profile is linked to your account. \
504	                 Contact an administrator to set up a contractor record.".into(),
505	            ))
506	    } else {
507	        Ok(user_id)
508	    }
509	}
