511	pub async fn subscribe(
512	    pool: web::Data<sqlx::PgPool>,
513	    body: web::Json<SubscribeBody>,
514	    auth: RequireViewContractors,
515	) -> AppResult<HttpResponse> {
516	    let body = body.into_inner();
517	    if !matches!(body.subscriber_type.as_str(), "dispatcher" | "contractor") {
518	        return Err(AppError::Validation(
519	            "subscriber_type must be 'dispatcher' or 'contractor'".into(),
520	        ));
521	    }
522	    if !matches!(body.target_type.as_str(), "shift" | "route") {
523	        return Err(AppError::Validation(
524	            "target_type must be 'shift' or 'route'".into(),
525	        ));
526	    }
527	
528	    let subscriber_id =
529	        resolve_subscriber_id(&pool, auth.id, &body.subscriber_type).await?;
530	
531	    SubscriptionRepo::new(&pool)
532	        .subscribe(&body.subscriber_type, subscriber_id, &body.target_type, body.target_id)
533	        .await?;
534	    Ok(HttpResponse::Ok().json(json!({ "ok": true })))
535	}
