137	/// Search / list published content.
138	///
139	/// `departure_from` / `departure_to` are optional ISO-8601 datetime strings
140	/// (e.g. `"2026-06-01T00:00:00Z"`) that filter content linked to routes with
141	/// departures within the given window.
142	pub async fn search_content(
143	    q:              Option<&str>,
144	    category:       Option<&str>,
145	    tag:            Option<&str>,
146	    departure_from: Option<&str>,
147	    departure_to:   Option<&str>,
148	    page:           i64,
149	    per_page:       i64,
150	) -> ApiResult<SearchResponse> {
151	    let mut url = format!("/api/v1/kiosk/content?page={page}&per_page={per_page}");
152	    if let Some(q) = q.filter(|s| !s.is_empty()) {
153	        url.push_str(&format!("&q={}", urlenc(q)));
154	    }
155	    if let Some(c) = category.filter(|s| !s.is_empty()) {
156	        url.push_str(&format!("&category={}", urlenc(c)));
157	    }
158	    if let Some(t) = tag.filter(|s| !s.is_empty()) {
159	        url.push_str(&format!("&tag={}", urlenc(t)));
160	    }
161	    if let Some(df) = departure_from.filter(|s| !s.is_empty()) {
162	        url.push_str(&format!("&departure_from={}", urlenc(df)));
163	    }
164	    if let Some(dt) = departure_to.filter(|s| !s.is_empty()) {
165	        url.push_str(&format!("&departure_to={}", urlenc(dt)));
166	    }
167	    get_public(&url).await
168	}
