235	fn parse_date_display(iso: &str) -> Option<String> {
236	    let parts: Vec<&str> = iso.split('-').collect();
237	    if parts.len() < 3 { return None; }
238	    let year  = parts[0];
239	    let month = parts[1].parse::<u32>().ok()?;
240	    let day   = parts[2].parse::<u32>().ok()?;
241	    let month_name = match month {
242	        1 => "Jan", 2 => "Feb", 3 => "Mar", 4 => "Apr",
243	        5 => "May", 6 => "Jun", 7 => "Jul", 8 => "Aug",
244	        9 => "Sep", 10 => "Oct", 11 => "Nov", 12 => "Dec",
245	        _ => return None,
246	    };
247	    Some(format!("{month_name} {day}, {year}"))
248	}
