1	//! Content quality scoring and similarity-based quarantine detection.
2	//!
3	//! ## Scoring weights
4	//!
5	//! | Dimension    | Weight | Basis                                               |
6	//! |--------------|--------|-----------------------------------------------------|
7	//! | Completeness | 50 %   | presence of title, body, category, tags, date, URL  |
8	//! | Accuracy     | 30 %   | structural validity + domain anomaly checks         |
9	//! | Timeliness   | 20 %   | publish_date age (recent = higher score)            |
10	//!
11	//! Total below 85 blocks publishing (see `QualityScore::is_publishable`).
12	//!
13	//! ## Domain anomaly checks (within Accuracy dimension)
14	//!
15	//! - Placeholder content (`lorem ipsum`, `[placeholder]`, etc.)
16	//! - Negative fare values in fare-category articles
17	//! - Stale disruption/delay notices (>30 days old)
18	//! - Suspicious test-data markers
19	//!
20	//! ## Similarity quarantine
21	//!
22	//! Uses PostgreSQL pg_trgm `similarity()` to detect near-duplicates in
23	//! `content_pages.body` at the threshold defined in `shared::rules`.
24	
25	use chrono::{NaiveDate, Utc};
26	use rust_decimal::Decimal;
27	use sqlx::PgPool;
28	use uuid::Uuid;
29	
30	use shared::QualityScore;
31	
32	use super::pipeline::TransformedItem;
33	use crate::error::AppResult;
34	
35	// ── Result ────────────────────────────────────────────────────────────────────
36	
37	#[derive(Debug)]
38	pub struct ScoredItem {
39	    pub score:             QualityScore,
40	    pub issues:            Vec<String>,
41	    pub is_quarantined:    bool,
42	    pub quarantine_reason: Option<String>,
43	}
44	
45	// ── Scorer ────────────────────────────────────────────────────────────────────
46	
47	pub struct QualityScorer;
48	
49	impl QualityScorer {
50	    /// Score a transformed item.
51	    ///
52	    /// `existing_content_id` — when re-scoring an existing page, pass its UUID
53	    /// so the similarity check excludes that page from the comparison set.
54	    pub async fn score(
55	        item:                &TransformedItem,
56	        pool:                &PgPool,
57	        existing_content_id: Option<Uuid>,
58	    ) -> AppResult<ScoredItem> {
59	        let mut issues: Vec<String> = Vec::new();
60	
61	        let completeness = score_completeness(item, &mut issues);
62	        let accuracy     = score_accuracy(item, &mut issues);
63	        let timeliness   = score_timeliness(item.publish_date, &mut issues);
64	
65	        let score = QualityScore::compute(
66	            dec(completeness),
67	            dec(accuracy),
68	            dec(timeliness),
69	        );
70	
71	        let (is_quarantined, quarantine_reason) =
72	            check_similarity(item, pool, existing_content_id).await?;
73	
74	        Ok(ScoredItem { score, issues, is_quarantined, quarantine_reason })
75	    }
76	}
77	
78	// ── Completeness (50 %) ───────────────────────────────────────────────────────
79	
80	fn score_completeness(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
81	    let mut present = 0usize;
82	    const FIELDS: usize = 6;
83	
84	    if !item.title.is_empty()    { present += 1; } else { issues.push("missing_title".into()); }
85	    if !item.body.is_empty()     { present += 1; } else { issues.push("missing_body".into()); }
86	    if item.category != "general"{ present += 1; } else { issues.push("default_category".into()); }
87	    if !item.tags.is_empty()     { present += 1; } else { issues.push("no_tags".into()); }
88	    if item.publish_date.is_some(){ present += 1; } else { issues.push("missing_publish_date".into()); }
89	    if item.source_url.is_some() { present += 1; } else { issues.push("missing_source_url".into()); }
90	
91	    (present as f64 / FIELDS as f64) * 100.0
92	}
93	
94	// ── Accuracy (30 %) ───────────────────────────────────────────────────────────
95	
96	fn score_accuracy(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
97	    let mut score: f64 = 100.0;
98	
99	    // ── Structural validity ───────────────────────────────────────────────
100	    if item.body.len() < 50 {
101	        score -= 40.0;
102	        issues.push("short_body".into());
103	    }
104	    if item.title.len() < 5 {
105	        score -= 20.0;
106	        issues.push("short_title".into());
107	    }
108	    if let Some(url) = &item.source_url {
109	        let ok = url.starts_with("http://")
110	            || url.starts_with("https://")
111	            || url.starts_with("file://");
112	        if !ok {
113	            score -= 20.0;
114	            issues.push("invalid_source_url_scheme".into());
115	        }
116	    }
117	    if item.tags.len() > 20 {
118	        score -= 10.0;
119	        issues.push("too_many_tags".into());
120	    }
121	
122	    // ── Domain anomaly checks ─────────────────────────────────────────────
123	    score -= check_anomalies(item, issues);
124	
125	    score.max(0.0)
126	}
127	
128	/// Detect railway-domain anomalies and return a total penalty (0..100).
129	fn check_anomalies(item: &TransformedItem, issues: &mut Vec<String>) -> f64 {
130	    let mut penalty: f64 = 0.0;
131	    let body_lower  = item.body.to_lowercase();
132	    let title_lower = item.title.to_lowercase();
133	
134	    // ── Placeholder / test content ────────────────────────────────────────
135	    if body_lower.contains("lorem ipsum") {
136	        issues.push("placeholder_content".into());
137	        penalty += 80.0;
138	    }
139	    if body_lower.contains("[placeholder]")
140	        || body_lower.contains("[to be completed]")
141	        || body_lower.contains("[tbd]")
142	        || body_lower.contains("todo: fill")
143	    {
144	        issues.push("incomplete_placeholder_content".into());
145	        penalty += 60.0;
146	    }
147	    if title_lower.contains("test article")
148	        || title_lower.contains("dummy content")
149	        || body_lower.starts_with("test ")
150	    {
151	        issues.push("test_content_detected".into());
152	        penalty += 50.0;
153	    }
154	
155	    // ── Negative fare values (fares/pricing category anomaly) ─────────────
156	    // Check for negative monetary patterns: -£N, - £N, or "negative fare/price/cost"
157	    if item.category == "fares" || body_lower.contains("fare") || body_lower.contains("price") {
158	        let has_negative_fare = body_lower.contains("-£")
159	            || body_lower.contains("- £")
160	            || body_lower.contains("-$")
161	            || (body_lower.contains("negative")
162	                && (body_lower.contains("fare")
163	                    || body_lower.contains("price")
164	                    || body_lower.contains("cost")));
165	        if has_negative_fare {
166	            issues.push("negative_fare_detected".into());
167	            penalty += 40.0;
168	        }
169	    }
170	
171	    // ── Stale disruption notices ──────────────────────────────────────────
172	    // Delay/disruption articles older than 30 days are anomalous (outdated operational data)
173	    if item.category == "delays" {
174	        if let Some(date) = item.publish_date {
175	            let today = Utc::now().date_naive();
176	            let age   = (today - date).num_days();
177	            if age > 30 {
178	                issues.push("stale_disruption_notice".into());
179	                penalty += 25.0;
180	            }
181	        }
182	    }
183	
184	    // ── Missing critical fields for specific categories ───────────────────
185	    // Fare articles without a source URL are suspicious (prices need authoritative source)
186	    if item.category == "fares" && item.source_url.is_none() {
187	        issues.push("fare_article_missing_source".into());
188	        penalty += 15.0;
189	    }
190	
191	    // ── Departure in the past ─────────────────────────────────────────────
192	    // Articles that reference a specific departure that has already occurred
193	    // are stale operational data and should be penalised heavily.
194	    if let Some(dep_date) = item.departure_date {
195	        let today = Utc::now().date_naive();
196	        if dep_date < today {
197	            issues.push(format!("departure_in_past:{dep_date}"));
198	            // Departed more than 7 days ago: heavy penalty (quarantine-grade).
199	            // Departed within 7 days: moderate penalty (old but perhaps still useful).
200	            let days_past = (today - dep_date).num_days();
201	            if days_past > 7 {
202	                penalty += 90.0; // ensures score falls below publishable threshold
203	            } else {
204	                penalty += 40.0;
205	            }
206	        }
207	    }
208	
209	    penalty
210	}
211	
212	// ── Timeliness (20 %) ─────────────────────────────────────────────────────────
213	
214	fn score_timeliness(publish_date: Option<NaiveDate>, issues: &mut Vec<String>) -> f64 {
215	    let today = Utc::now().date_naive();
216	    match publish_date {
217	        None => {
218	            issues.push("unknown_publish_date".into());
219	            50.0
220	        }
221	        Some(date) => {
222	            let age = (today - date).num_days();
223	            if age < 0      { 100.0 }
224	            else if age <= 30  { 100.0 }
225	            else if age <= 90  { 70.0 }
226	            else if age <= 365 { 40.0 }
227	            else {
228	                issues.push("stale_content".into());
229	                10.0
230	            }
231	        }
232	    }
233	}
234	
235	// ── Similarity quarantine ─────────────────────────────────────────────────────
236	
237	/// Check whether the item body is a near-duplicate of any existing content.
238	///
239	/// Returns `(true, Some(reason))` when a duplicate is found at the configured
240	/// similarity threshold (`shared::rules::SIMILARITY_QUARANTINE`).
241	async fn check_similarity(
242	    item:                &TransformedItem,
243	    pool:                &PgPool,
244	    existing_content_id: Option<Uuid>,
245	) -> AppResult<(bool, Option<String>)> {
246	    // Short stubs would produce too many false-positive similarity matches.
247	    if item.body.len() < 100 {
248	        return Ok((false, None));
249	    }
250	
251	    let threshold = shared::rules::SIMILARITY_QUARANTINE as f32;
252	
253	    // similarity() returns float4 (real) in PostgreSQL, so we compare as real.
254	    // We cast the result to float8 for decoding into Rust f64.
255	    let row: Option<(Uuid, f64)> = sqlx::query_as(
256	        "SELECT id, similarity(body, $1)::float8 AS sim
257	         FROM content_pages
258	         WHERE ($2::UUID IS NULL OR id <> $2)
259	           AND similarity(body, $1) >= $3::real
260	         ORDER BY sim DESC
261	         LIMIT 1",
262	    )
263	    .bind(&item.body)
264	    .bind(existing_content_id)
265	    .bind(threshold)
266	    .fetch_optional(pool)
267	    .await
268	    .map_err(crate::error::AppError::Database)?;
269	
270	    match row {
271	        Some((dup_id, sim)) => Ok((
272	            true,
273	            Some(format!("near_duplicate of content_id={dup_id} (similarity={sim:.2})")),
274	        )),
275	        None => Ok((false, None)),
276	    }
277	}
278	
279	// ── Decimal helper ────────────────────────────────────────────────────────────
280	
281	fn dec(v: f64) -> Decimal {
282	    Decimal::try_from(v).unwrap_or_default()
283	}
