444	fn results_panel(
445	    results:      &UseStateHandle<Option<SearchResponse>>,
446	    loading:      &UseStateHandle<bool>,
447	    error:        &UseStateHandle<Option<String>>,
448	    active_q:     &str,
449	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
450	) -> Html {
451	    if **loading {
452	        return html! {
453	            <div class="space-y-4">
454	                { for (0..6).map(|_| html! {
455	                    <div class="bg-white rounded-2xl border border-slate-200 p-5 animate-pulse">
456	                        <div class="h-4 bg-slate-200 rounded-full w-20 mb-3"></div>
457	                        <div class="h-5 bg-slate-200 rounded w-4/5 mb-2"></div>
458	                        <div class="h-3 bg-slate-100 rounded w-16"></div>
459	                    </div>
460	                }) }
461	            </div>
462	        };
463	    }
464	
465	    if let Some(msg) = &**error {
466	        return html! {
467	            <div class="rounded-xl bg-red-50 border border-red-200 p-6 text-red-700">
468	                <p class="font-semibold mb-1">{"Unable to load results"}</p>
469	                <p class="text-sm">{ msg.clone() }</p>
470	            </div>
471	        };
472	    }
473	
474	    if let Some(resp) = &**results {
475	        let heading = match resp.search_type.as_deref() {
476	            Some("fts")   => format!("{} results for \"{}\"", resp.total, active_q),
477	            Some("fuzzy") => format!(
478	                "Showing approximate matches for \"{}\" ({} results)",
479	                active_q, resp.total
480	            ),
481	            _ if !active_q.is_empty() => format!("No results for \"{}\"", active_q),
482	            _ => format!("{} articles", resp.total),
483	        };
484	
485	        if resp.items.is_empty() {
486	            return html! {
487	                <div class="text-center py-16">
488	                    <p class="text-lg font-semibold text-slate-700 mb-2">
489	                        { format!("No results for \"{active_q}\"") }
490	                    </p>
491	                    <p class="text-slate-500 text-sm">
492	                        {"Try different keywords, or browse by category."}
493	                    </p>
494	                </div>
495	            };
496	        }
497	
498	        let is_fuzzy = resp.search_type.as_deref() == Some("fuzzy");
499	
500	        html! {
501	            <div>
502	                <div class="flex items-center justify-between mb-4">
503	                    <p class="text-sm text-slate-600">{ heading }</p>
504	                    if is_fuzzy {
505	                        <span class="text-xs text-amber-700 bg-amber-50 border border-amber-200
506	                                     rounded-full px-2.5 py-1 font-medium">
507	                            {"Approximate matches"}
508	                        </span>
509	                    }
510	                </div>
511	
512	                <div class="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
513	                    { for resp.items.iter().map(article_card) }
514	                </div>
515	
516	                // Pagination
517	                if resp.total_pages > 1 {
518	                    { pagination(resp.page, resp.total_pages, make_page_cb) }
519	                }
520	            </div>
521	        }
522	    } else {
523	        html! {
524	            <div class="text-center py-16 text-slate-400">
525	                <p>{"Start typing to search, or browse by category."}</p>
526	            </div>
527	        }
528	    }
529	}
530	
531	fn pagination(
532	    current:      i64,
533	    total:        i64,
534	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
535	) -> Html {
536	    html! {
537	        <div class="flex items-center justify-center gap-2">
538	            <button
539	                onclick={make_page_cb(1)}
540	                disabled={current == 1}
541	                class={page_btn_class(false, current == 1)}
542	            >{"«"}</button>
543	            <button
544	                onclick={make_page_cb((current - 1).max(1))}
545	                disabled={current == 1}
546	                class={page_btn_class(false, current == 1)}
547	            >{"‹"}</button>
548	
549	            { for visible_pages(current, total).into_iter().map(|p| {
550	                let active = p == current;
551	                html! {
552	                    <button
553	                        key={p}
554	                        onclick={make_page_cb(p)}
555	                        class={page_btn_class(active, false)}
556	                    >
557	                        { p }
558	                    </button>
559	                }
560	            }) }
561	
562	            <button
563	                onclick={make_page_cb((current + 1).min(total))}
564	                disabled={current == total}
565	                class={page_btn_class(false, current == total)}
566	            >{"›"}</button>
567	            <button
568	                onclick={make_page_cb(total)}
569	                disabled={current == total}
570	                class={page_btn_class(false, current == total)}
571	            >{"»"}</button>
572	        </div>
573	    }
574	}
575	
576	fn visible_pages(current: i64, total: i64) -> Vec<i64> {
577	    let window = 2i64;
578	    let start  = (current - window).max(1);
579	    let end    = (current + window).min(total);
580	    (start..=end).collect()
581	}
582	
583	fn page_btn_class(active: bool, disabled: bool) -> &'static str {
584	    if disabled      { "w-9 h-9 rounded-lg text-sm text-slate-300 cursor-not-allowed" }
585	    else if active   { "w-9 h-9 rounded-lg text-sm bg-indigo-700 text-white font-bold" }
586	    else             { "w-9 h-9 rounded-lg text-sm border border-slate-200 \
587	                        text-slate-700 hover:bg-slate-50" }
588	}
589	
590	fn sidebar_btn_class(active: bool) -> &'static str {
591	    if active {
592	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
593	         bg-indigo-50 text-indigo-700 font-semibold text-sm"
594	    } else {
595	        "w-full flex items-center text-left px-3 py-2 rounded-lg \
596	         text-slate-700 text-sm hover:bg-slate-50 transition"
597	    }
598	}
