351	fn archive_pagination(
352	    current:      i64,
353	    total:        i64,
354	    make_page_cb: &dyn Fn(i64) -> Callback<MouseEvent>,
355	) -> Html {
356	    let window: i64 = 2;
357	    let pages: Vec<i64> = ((current - window).max(1)..=(current + window).min(total)).collect();
358	
359	    html! {
360	        <div class="flex items-center justify-center gap-2 mt-4">
361	            <button onclick={make_page_cb(1)} disabled={current == 1}
362	                class={page_btn_class(false, current == 1)}>{"«"}</button>
363	            <button onclick={make_page_cb((current - 1).max(1))} disabled={current == 1}
364	                class={page_btn_class(false, current == 1)}>{"‹"}</button>
365	
366	            { for pages.into_iter().map(|p| html! {
367	                <button key={p} onclick={make_page_cb(p)}
368	                    class={page_btn_class(p == current, false)}>{ p }</button>
369	            }) }
370	
371	            <button onclick={make_page_cb((current + 1).min(total))} disabled={current == total}
372	                class={page_btn_class(false, current == total)}>{"›"}</button>
373	            <button onclick={make_page_cb(total)} disabled={current == total}
374	                class={page_btn_class(false, current == total)}>{"»"}</button>
375	        </div>
376	    }
377	}
