1	//! Source readers for the offline collection engine.
2	//!
3	//! All source types in this project are **offline** (file-system based).
4	//! Readers implement the [`SourceReader`] trait and return up to `PAGE_SIZE`
5	//! items per call together with a resumption cursor.
6	//!
7	//! ## Cursor format (JSON)
8	//!
9	//! ```json
10	//! { "file_index": 3, "item_offset": 12 }
11	//! ```
12	//!
13	//! - `file_index`  — 0-based index into the sorted list of `.json` files under
14	//!                   the source's `base_path`.
15	//! - `item_offset` — 0-based position within that file's item array.
16	//!
17	//! `None` next-cursor signals the source is exhausted for this run.
18	
19	use std::path::Path;
20	
21	use async_trait::async_trait;
22	use serde::{Deserialize, Serialize};
23	use serde_json::Value;
24	use tracing::{debug, warn};
25	
26	use super::pipeline::RawItem;
