28	
29	const PAGE_SIZE: usize = 50;
30	
31	// ── Cursor ────────────────────────────────────────────────────────────────────
32	
33	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
34	pub struct FileCursor {
35	    pub file_index:  usize,
36	    pub item_offset: usize,
37	}
38	
39	impl FileCursor {
40	    pub fn from_value(v: &Value) -> Self {
41	        serde_json::from_value(v.clone()).unwrap_or_default()
42	    }
43	
44	    pub fn to_value(&self) -> Value {
45	        serde_json::to_value(self).unwrap_or(Value::Null)
46	    }
47	}
