50	
51	/// Yields pages of raw items from an underlying data source.
52	#[async_trait]
53	pub trait SourceReader: Send + Sync {
54	    async fn read_page(
55	        &self,
56	        source: &CrawlSource,
57	        cursor: Option<Value>,
58	    ) -> Result<(Vec<RawItem>, Option<Value>), String>;
59	}
