106	// ── Shared implementation ─────────────────────────────────────────────────────
107	
108	async fn read_from_dir(
109	    dir:    &str,
110	    cursor: Option<Value>,
111	) -> Result<(Vec<RawItem>, Option<Value>), String> {
112	    let path = Path::new(dir);
113	    let mut files = collect_json_files(path).await
114	        .map_err(|e| format!("Cannot read directory '{dir}': {e}"))?;
115	
116	    files.sort(); // deterministic order across runs
117	
118	    if files.is_empty() {
119	        return Ok((Vec::new(), None));
120	    }
121	
122	    let cur = cursor.as_ref().map(FileCursor::from_value).unwrap_or_default();
123	    let mut file_idx = cur.file_index;
124	    let mut item_off = cur.item_offset;
125	    let mut collected: Vec<RawItem> = Vec::with_capacity(PAGE_SIZE);
126	
127	    while collected.len() < PAGE_SIZE && file_idx < files.len() {
128	        let file_path = &files[file_idx];
129	        debug!(file = %file_path.display(), "Reading source file");
130	
131	        let bytes = tokio::fs::read(file_path)
132	            .await
133	            .map_err(|e| format!("Cannot read '{}': {e}", file_path.display()))?;
134	
135	        let json: Value = serde_json::from_slice(&bytes)
136	            .map_err(|e| format!("JSON parse error in '{}': {e}", file_path.display()))?;
137	
138	        let items_json: Vec<Value> = match json {
139	            Value::Array(arr)  => arr,
140	            obj @ Value::Object(_) => vec![obj],
141	            _ => {
142	                warn!(file = %file_path.display(), "Unexpected JSON root type — skipping");
143	                file_idx += 1;
144	                item_off  = 0;
145	                continue;
146	            }
147	        };
148	
149	        let remaining = PAGE_SIZE - collected.len();
150	        let start     = item_off.min(items_json.len());
151	        let end       = (start + remaining).min(items_json.len());
152	
153	        for v in &items_json[start..end] {
154	            match serde_json::from_value::<RawItem>(v.clone()) {
155	                Ok(item)  => collected.push(item),
156	                Err(e)    => warn!("Skipping malformed item: {e}"),
157	            }
158	        }
159	
160	        item_off = end;
161	        if item_off >= items_json.len() {
162	            file_idx += 1;
163	            item_off  = 0;
164	        }
165	    }
166	
167	    let next_cursor = if file_idx < files.len() {
168	        Some(FileCursor { file_index: file_idx, item_offset: item_off }.to_value())
169	    } else {
170	        None
171	    };
172	
173	    Ok((collected, next_cursor))
174	}
175	
176	/// Collect all `.json` file paths in a directory (non-recursive).
177	async fn collect_json_files(dir: &Path) -> std::io::Result<Vec<std::path::PathBuf>> {
178	    let mut read_dir = tokio::fs::read_dir(dir).await?;
179	    let mut paths    = Vec::new();
180	
181	    while let Some(entry) = read_dir.next_entry().await? {
182	        let p = entry.path();
183	        if p.extension().map(|x| x.eq_ignore_ascii_case("json")).unwrap_or(false) {
184	            paths.push(p);
185	        }
186	    }
187	
188	    Ok(paths)
189	}
