191	// ── Factory ───────────────────────────────────────────────────────────────────
192	
193	/// Return the appropriate `SourceReader` for the given `source_type` string.
194	pub fn reader_for(source_type: &str) -> Box<dyn SourceReader> {
195	    match source_type {
196	        "internal_mirror" => Box::new(InternalMirrorReader),
197	        _                 => Box::new(LocalPackageReader),
198	    }
199	}
