//!   "departure_time":  "2026-04-10T08:30:00Z",
//!   "arrival_time":    "2026-04-10T12:00:00Z",
//!   "platform":        "3A",
//!   "status":          "scheduled",
//!   "delay_minutes":   0,
//!   "inventory": [
//!     { "seat_class_code": "ECO", "total_seats": 200, "available_seats": 180 }
//!   ]
//! }
//! ```
//!
