    let on_unsub = {
        let subs    = subs.clone();
        let sub_err = sub_err.clone();
        let token   = token.clone();
        Callback::from(move |(target_type, target_id): (String, String)| {
            let (subs, err, token) = (subs.clone(), sub_err.clone(), token.clone());
